const a=JSON.parse('{"workId":"cai-gen-tan","chapter":{"id":"cai-gen-tan_ch-5","workId":"cai-gen-tan","order":5,"title":"素位","difficulty":3,"estimatedMinutes":53,"passageIds":["cai-gen-tan_ch-5_p-1","cai-gen-tan_ch-5_p-2","cai-gen-tan_ch-5_p-3","cai-gen-tan_ch-5_p-4","cai-gen-tan_ch-5_p-5","cai-gen-tan_ch-5_p-6","cai-gen-tan_ch-5_p-7","cai-gen-tan_ch-5_p-8","cai-gen-tan_ch-5_p-9","cai-gen-tan_ch-5_p-10","cai-gen-tan_ch-5_p-11","cai-gen-tan_ch-5_p-12","cai-gen-tan_ch-5_p-13","cai-gen-tan_ch-5_p-14","cai-gen-tan_ch-5_p-15","cai-gen-tan_ch-5_p-16","cai-gen-tan_ch-5_p-17","cai-gen-tan_ch-5_p-18","cai-gen-tan_ch-5_p-19","cai-gen-tan_ch-5_p-20","cai-gen-tan_ch-5_p-21","cai-gen-tan_ch-5_p-22","cai-gen-tan_ch-5_p-23","cai-gen-tan_ch-5_p-24","cai-gen-tan_ch-5_p-25","cai-gen-tan_ch-5_p-26","cai-gen-tan_ch-5_p-27","cai-gen-tan_ch-5_p-28","cai-gen-tan_ch-5_p-29","cai-gen-tan_ch-5_p-30","cai-gen-tan_ch-5_p-31","cai-gen-tan_ch-5_p-32","cai-gen-tan_ch-5_p-33","cai-gen-tan_ch-5_p-34","cai-gen-tan_ch-5_p-35","cai-gen-tan_ch-5_p-36","cai-gen-tan_ch-5_p-37","cai-gen-tan_ch-5_p-38","cai-gen-tan_ch-5_p-39","cai-gen-tan_ch-5_p-40","cai-gen-tan_ch-5_p-41","cai-gen-tan_ch-5_p-42","cai-gen-tan_ch-5_p-43","cai-gen-tan_ch-5_p-44","cai-gen-tan_ch-5_p-45","cai-gen-tan_ch-5_p-46","cai-gen-tan_ch-5_p-47","cai-gen-tan_ch-5_p-48","cai-gen-tan_ch-5_p-49","cai-gen-tan_ch-5_p-50","cai-gen-tan_ch-5_p-51","cai-gen-tan_ch-5_p-52","cai-gen-tan_ch-5_p-53","cai-gen-tan_ch-5_p-54","cai-gen-tan_ch-5_p-55","cai-gen-tan_ch-5_p-56","cai-gen-tan_ch-5_p-57","cai-gen-tan_ch-5_p-58","cai-gen-tan_ch-5_p-59","cai-gen-tan_ch-5_p-60","cai-gen-tan_ch-5_p-61","cai-gen-tan_ch-5_p-62","cai-gen-tan_ch-5_p-63","cai-gen-tan_ch-5_p-64","cai-gen-tan_ch-5_p-65","cai-gen-tan_ch-5_p-66","cai-gen-tan_ch-5_p-67","cai-gen-tan_ch-5_p-68","cai-gen-tan_ch-5_p-69","cai-gen-tan_ch-5_p-70","cai-gen-tan_ch-5_p-71","cai-gen-tan_ch-5_p-72","cai-gen-tan_ch-5_p-73","cai-gen-tan_ch-5_p-74"],"tags":["文學","處世","素位"]},"passages":[{"id":"cai-gen-tan_ch-5_p-1","chapterId":"cai-gen-tan_ch-5","order":1,"canonicalText":"道是一件公眾的物事，當隨人而接引；學是一個尋常的家飯，當隨事而警惕。","sentenceIds":["cai-gen-tan_ch-5_p-1_s-1","cai-gen-tan_ch-5_p-1_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"真理大道是一件天下人所共有的事物，應當順應每個人的資質與緣分來引導他們去認識；學問修養就像是一頓平常的家常便飯，應當在處理各種日常事務時，隨時自我警惕與反省。","analysis":"【訓詁與名物】\\\\n「道」指宇宙人生的最高真理與法則；「公眾的物事」意謂並非一人所私有，而是普世皆準的；「接引」原為佛教語，指佛菩薩引導眾生，此指教導、引領；「學」指為學修身；「尋常的家飯」喻指日常生活中不可或缺且平實無奇的事物；「警惕」指隨時警覺、省察。\\\\n【章法與結構】\\\\n本段為一對偶句，上聯論「道」，下聯論「學」。「公眾的物事」對「尋常的家飯」，將高深的「道」與「學」用極為通俗、生活化的語言進行詮釋。「隨人而接引」對「隨事而警惕」，則點出了實踐的方法。句式整齊，語氣平易近人，說理卻深具透視力。\\\\n【思想與義理】\\\\n作者打破了世人對「道」與「學」高高在上的迷思。首先，指出「道」是普世的，因此傳道、弘法不應有門派之見或高下之分，而應「因材施教」，隨順眾生的根機予以引導。其次，點明「學問」不是脫離現實的清談，而是如同吃飯一樣不可或缺的日常生活實踐，必須在每一件具體的事務中去體會、去警省（即王陽明所謂的「事上磨練」）。這體現了儒家道不遠人、知行合一的實用主義精神與平民化色彩。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-2","chapterId":"cai-gen-tan_ch-5","order":2,"canonicalText":"念頭寬厚的，如春風煦育，萬物遭之而生；念頭忌尅的，如朔雪陰凝，萬物遭之而死。","sentenceIds":["cai-gen-tan_ch-5_p-2_s-1","cai-gen-tan_ch-5_p-2_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心思寬大厚道的人，就像溫暖的春風吹拂孕育著大地，萬物遇到它便會生機盎然地生長；心思嫉妒刻薄的人，就像北方的冰雪陰冷凝結，萬物遇到它便會失去生機而枯萎死亡。","analysis":"【訓詁與名物】\\\\n「念頭」指內心的想法與動機；「寬厚」指寬容仁厚；「煦育」指溫暖撫育，如春陽和風滋養萬物；「忌尅」同「忌刻」，指心胸狹隘、嫉妒刻薄；「朔雪」指北方的冰雪，代表極度寒冷；「陰凝」指陰氣凝結、寒冷肅殺。\\\\n【章法與結構】\\\\n這是一段極為工整的對比與比喻句。上聯寫「寬厚」，下聯寫「忌尅」；「春風煦育」對「朔雪陰凝」，「遭之而生」對「遭之而死」。透過春天與冬天的強烈自然景象對比，將抽象的心理活動轉化為具體的視覺與溫度感受，極大地增強了文字的感染力與說服力。\\\\n【思想與義理】\\\\n此段深具儒家「仁者愛人」的底蘊與道家「氣」的感應理論。作者認為，人的一念之間蘊含著巨大的能量，能直接影響周遭的環境與人事。寬厚的心念如同春風，散發出正向的生機，能帶來和諧與發展，成就他人；而忌刻的心念則如同寒冬，散發出負面的肅殺之氣，會帶來破壞與毀滅，傷害他人。這不僅是道德層面的勸誡，更揭示了心性與外界磁場相互感應的宇宙法則，提醒我們應時時保持內心的溫暖與善意。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-3","chapterId":"cai-gen-tan_ch-5","order":3,"canonicalText":"勤者敏於德義，而世人借勤以濟其貪；儉者淡於貨利，而世人假儉以飾其吝。君子持身之符，反為小人營私之具矣，惜哉！","sentenceIds":["cai-gen-tan_ch-5_p-3_s-1","cai-gen-tan_ch-5_p-3_s-2","cai-gen-tan_ch-5_p-3_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"勤奮的人本來應該是敏捷地去實踐道德與正義，但世俗之人卻常常藉著勤奮的名義來滿足自己的貪婪；節儉的人本來應該是對金錢利益看得很淡薄，但世俗之人卻常常假借節儉的名義來掩飾自己的吝嗇。君子用來修身養性的美好準則，反而變成了小人謀取私利的工具，這真是太可惜了啊！","analysis":"【訓詁與名物】\\\\n「敏於德義」指在修行道德與伸張正義上積極敏捷；「濟其貪」意為滿足其貪慾，「濟」作助長、滿足解；「淡於貨利」指對財物利益毫不計較；「飾其吝」指掩飾其小氣吝嗇；「持身之符」指修身立德的信條與法寶；「營私之具」指謀求私利的工具。\\\\n【章法與結構】\\\\n全段分為兩層。第一層以對比手法，先揭示「勤」與「儉」的本義（敏於德義、淡於貨利），再點出世俗小人的扭曲作法（借勤以濟其貪、假儉以飾其吝），兩兩相對，極具諷刺意味。第二層則以一聲長歎「惜哉」作結，總結前文，將君子的「持身之符」與小人的「營私之具」對立起來，抒發作者的無奈與感慨。\\\\n【思想與義理】\\\\n這段文字深刻地批判了社會上偽善的現象。儒家推崇「勤儉」為美德，但美德若失去了「公義」與「淡泊」的核心動機，便會淪為惡行的遮羞布。作者敏銳地指出，許多看似勤奮的人，實質上是被貪慾驅使的「工作狂」；許多看似節儉的人，骨子裡只是守財奴。這提醒世人，評價一個人的品行，不能僅看其表面行為（勤與儉），更要洞察其背後的存心與動機（是為了德義還是貪吝）。這是一種直指人心的道德透視，也是對世風日下的深刻反思。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-4","chapterId":"cai-gen-tan_ch-5","order":4,"canonicalText":"人之過誤宜恕，而在己則不可恕；己之困辱宜忍，而在人則不可忍。","sentenceIds":["cai-gen-tan_ch-5_p-4_s-1","cai-gen-tan_ch-5_p-4_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"別人的過失與錯誤，我們應該要寬恕原諒，但如果是自己犯了過錯，就絕對不能輕易原諒自己；自己遭受的困苦與屈辱，我們應該要忍耐承受，但如果是別人遭受到困苦與屈辱，我們就絕對不能袖手旁觀、忍心不顧。","analysis":"【訓詁與名物】\\\\n「過誤」指過失與錯誤；「恕」指寬恕、原諒；「困辱」指困頓與屈辱；「忍」在前句指忍耐、承受，在後句（不可忍）則轉為「忍心」、「無動於衷」之意，詞意因上下文而產生微妙變化。\\\\n【章法與結構】\\\\n此段為極其精鍊的兩組對比句。第一組對比「人」與「己」在面對「過誤」時的不同態度（宜恕 vs. 不可恕）；第二組對比「己」與「人」在面對「困辱」時的不同態度（宜忍 vs. 不可忍）。句法對稱，邏輯嚴密，透過「宜」與「不可」的強烈反差，將嚴於律己、寬以待人的道德標準刻畫得入木三分。\\\\n【思想與義理】\\\\n本段是儒家「嚴以律己，寬以待人」修養觀的極致展現。在面對過失時，君子應具備極高的自我要求（不可恕己），同時對他人的軟弱抱持同理心（恕人）。更深刻的是下半句，在面對苦難時，君子對自身的逆境能坦然處之（忍己），但看到他人受難，卻會激發出惻隱之心與正義感，絕不袖手旁觀（不忍人）。這種把對自己的嚴格要求與對他人的深厚悲憫結合在一起的態度，正是大乘菩薩道與儒家仁人志士的共同特徵，展現了極高的人格光輝。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-5","chapterId":"cai-gen-tan_ch-5","order":5,"canonicalText":"恩宜自淡而濃，先濃後淡者人忘其惠；威宜自嚴而寬，先寬後嚴者人怨其酷。","sentenceIds":["cai-gen-tan_ch-5_p-5_s-1","cai-gen-tan_ch-5_p-5_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"施予恩惠應當由平淡逐漸走向濃厚，如果一開始很濃厚而後來逐漸變平淡，人們就會忘記你的恩德；樹立威信應當由嚴厲逐漸走向寬容，如果一開始很寬鬆而後來突然變嚴厲，人們就會怨恨你的殘酷無情。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 297 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「恩宜自淡而濃先濃後淡者人忘其惠威宜自嚴而……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「恩」、「宜」、「自」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-5）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-6","chapterId":"cai-gen-tan_ch-5","order":6,"canonicalText":"士君子處權門要路，操履要嚴明，心氣要和易。毋少隨而近腥羶之黨，亦毋過激而犯蜂蠆之毒。","sentenceIds":["cai-gen-tan_ch-5_p-6_s-1","cai-gen-tan_ch-5_p-6_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"讀書人或君子處於權力核心與重要地位時，自己的操守與行為要嚴格且光明磊落，但心境與態度要溫和容易親近。既不要有絲毫的隨波逐流去接近那些諂媚、骯髒的權貴朋黨，也不要採取過於激烈的對抗手段而招致小人如馬蜂毒蛇般的狠毒報復。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 298 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「士君子處權門要路操履要嚴明心氣要和易毋少……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「士」、「君」、「子」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-6）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-7","chapterId":"cai-gen-tan_ch-5","order":7,"canonicalText":"遇欺詐的人，以誠心感動之；遇暴戾的人，以和氣燻蒸之；遇傾邪私曲的人，以名義氣節激勵之。天下無不入我陶鎔中矣。","sentenceIds":["cai-gen-tan_ch-5_p-7_s-1","cai-gen-tan_ch-5_p-7_s-2","cai-gen-tan_ch-5_p-7_s-3","cai-gen-tan_ch-5_p-7_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到狡猾欺詐的人，就要用真誠的心去感動他；遇到粗暴兇狠的人，就要用溫和的態度去感染他；遇到行為偏邪、自私自利的人，就要用大義與氣節去激勵他。如果能做到這樣，天下就沒有人不能被我的德行所感化和鎔鑄了。","analysis":"【訓詁與名物】「暴戾」指脾氣暴躁、行為兇狠。「燻蒸」原指熱氣上升，在此比喻用溫和的態度慢慢感化。「傾邪私曲」指行為不正、心術偏狹且自私。「名義氣節」指名分、道義與高尚的節操。「陶鎔」原指燒冶金屬，比喻教育、感化與塑造人的品格。\\\\n【章法與結構】本段採取排比與總結相結合的結構。前三句分別針對三種負麪人格（欺詐、暴戾、傾邪），提出相對應的感化策略（誠心、和氣、氣節），句式整齊劃一；最後一句「天下無不入我陶鎔中矣」作為強而有力的總結，將個人的道德修養昇華至改變天下的境界。\\\\n【思想與義理】此段反映了儒家「以德服人」的崇高社會理想。面對社會中的種種惡行與劣根性，作者並不主張以暴制暴或以牙還牙，而是提倡以極大的包容力與針對性的道德力量（誠、和、義）去轉化對方。這種「陶鎔」天下的氣魄，展現了傳統讀書人對於道德感化力量的絕對自信，以及儒家積極入世、兼善天下的情懷。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-8","chapterId":"cai-gen-tan_ch-5","order":8,"canonicalText":"一念慈祥，可以醞釀兩間和氣；寸心潔白，可以昭垂百代清芬。","sentenceIds":["cai-gen-tan_ch-5_p-8_s-1","cai-gen-tan_ch-5_p-8_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心中只要存有一絲慈祥的善念，就可以為天地之間帶來溫暖祥和的氣氛；內心保持一寸純潔無瑕的光明，就可以為後代子孫留下千百年的清白芬芳與榜樣。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 300 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「一念慈祥可以醞釀兩間和氣寸心潔白可以昭垂……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「一」、「念」、「慈」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-8）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-9","chapterId":"cai-gen-tan_ch-5","order":9,"canonicalText":"陰謀怪習、異行奇能，俱是涉世的禍胎。只一個庸德庸行，便可以完混沌而招和平。","sentenceIds":["cai-gen-tan_ch-5_p-9_s-1","cai-gen-tan_ch-5_p-9_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"陰險的計謀、怪異的習慣、驚世駭俗的行為和奇特的技能，這些全都是在社會上立足時會引發災禍的根源。只有保持平凡的道德和日常的行為，才可以保全人天生純真的本性，並招來平和安寧的生活。","analysis":"【訓詁與名物】「陰謀怪習」指暗中的算計與異於常理的習慣。「禍胎」指引發災禍的根源。「庸德庸行」的「庸」指平常、普通，即指日常生活中平凡而正當的道德與行為。「完混沌」的「混沌」借用《莊子》典故，指未被世俗智巧破壞的純真自然狀態。「完」作動詞，保全。\\\\n【章法與結構】本段為極具張力的正反對比結構。首句將「陰謀怪習」與「異行奇能」並列為「禍胎」，予以全盤否定；次句則獨尊「庸德庸行」，將其視為保全真性、招致和平的唯一途徑。兩相映照，主旨鮮明。\\\\n【思想與義理】這段話深刻體現了《菜根譚》融合儒道兩家的中庸處世哲學。它反對世俗對於「奇」與「異」的過度推崇，認為那些標新立異、炫耀智巧的行為，往往會打破人際關係的和諧，最終招致災禍。相反地，回歸平凡（庸德庸行），堅守中庸之道，不僅能符合儒家的日常倫理，更能保全道家所推崇的自然純真（完混沌），這才是最穩健、最長久的生存智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-10","chapterId":"cai-gen-tan_ch-5","order":10,"canonicalText":"語雲：「登山耐險路，踏雪耐危橋」。一耐字極有意味。如傾險之人情、坎坷之世道，若不得一耐字撐持過去，幾何不墜入榛莽坑塹哉！","sentenceIds":["cai-gen-tan_ch-5_p-10_s-1","cai-gen-tan_ch-5_p-10_s-2","cai-gen-tan_ch-5_p-10_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"俗語說：「攀登山峯時必須忍耐路途的險峻，踏雪而行時必須忍耐橋樑的危險。」這一個「耐」字蘊含著極深長的意味。就像那險惡難測的人情世故、崎嶇坎坷的世間道路，如果不能憑藉著一個「耐」字來支撐熬過，有幾個人能不跌入那布滿荊棘的荒野與深坑之中呢！","analysis":"【訓詁與名物】「語雲」即俗語說。「耐」指忍耐、承受。「危橋」指危險不穩的橋樑。「傾險」指險惡、陰險傾軋。「坎坷」指道路不平，比喻人生境遇不順利。「撐持」指支撐、維持。「幾何」指有多少、幾個人。「榛莽」指叢生的雜樹亂草，比喻險惡的環境。「坑塹」指深坑與溝渠，比喻災難與陷阱。\\\\n【章法與結構】先引述兩句俗諺「登山耐險路，踏雪耐危橋」作為開端，點出核心字眼「耐」。接著以「傾險之人情」與「坎坷之世道」將自然之險轉化為人事之難。最後以「若不得...幾何不...」的反問句式收尾，語氣強烈，發人深省。\\\\n【思想與義理】本文探討了「忍耐」在人生道路上的重要性。世道艱難，人心叵測，挫折與逆境是人生的常態。作者強調，在面對人生的低谷與險境時，最重要的不是聰明才智，而是堅韌不拔的毅力與忍耐力。唯有具備「耐」的功夫，才能在荊棘與陷阱中穩住腳步，度過難關，這是一種極具韌性的生命智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-11","chapterId":"cai-gen-tan_ch-5","order":11,"canonicalText":"誇逞功業炫耀文章，皆是靠外物做人。不知心體瑩然，本來不失，即無寸功隻字，亦自有堂堂正正做人處。","sentenceIds":["cai-gen-tan_ch-5_p-11_s-1","cai-gen-tan_ch-5_p-11_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"誇耀自己的豐功偉業或賣弄自己的華麗文章，這些都是依靠外在的事物來建立自己的人格。卻不知道只要內心保持清明純潔，不失去原本善良的本性，即使沒有建立任何微小的功勞、沒有寫下任何一個字，也自然有其堂堂正正做人的價值與基礎。","analysis":"【訓詁與名物】「誇逞」指誇耀、賣弄。「炫耀」指誇大顯露。「文章」指文辭、才華。「外物」指心靈之外的物質、名聲或成就。「心體」指人的內心與本性。「瑩然」指光潔明亮貌。「寸功」指微小的功勞。「隻字」指極少的文字。「堂堂正正」指光明磊落、正直無私。\\\\n【章法與結構】首句以「誇逞功業炫耀文章」點出世俗追逐外物的病態，並以「皆是靠外物做人」作結。次句則以「不知心體瑩然」進行反思，最後以「即無...亦自有...」的讓步假設句式，強調內在道德修養的絕對價值。先破後立，說理透徹。\\\\n【思想與義理】此段批判了世人以功名才華來衡量人生價值的功利主義。作者指出，功業與文章都屬於外在的附庸，若以此作為立身之本，容易迷失自我。真正的價值在於「心體瑩然」，即保有一顆光明純正的良心。這呼應了儒家「君子務本」的思想，認為道德修養才是做人的根本，有了這份坦蕩，即使平凡無奇，依然是個值得尊敬的人。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-12","chapterId":"cai-gen-tan_ch-5","order":12,"canonicalText":"不昧己心，不拂人情，不竭物力，三者可以為天地立心，為生民立命，為子孫造福。","sentenceIds":["cai-gen-tan_ch-5_p-12_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不欺瞞自己的良心，不違背常理與人情，不耗盡自然的物力，做到這三點就可以算是為天地確立道德的核心，為百姓建立生命的保障，並為後代子孫創造長遠的福祉。","analysis":"【訓詁與名物】「昧」指欺瞞、蒙蔽。「己心」即自己的良心。「拂」指違背、逆轉。「人情」指人之常情。「竭」指窮盡、耗盡。「物力」指自然界的資源與物質。「為天地立心，為生民立命」語出宋代大儒張載的「橫渠四句」，此處引申為確立道德標準與保障民眾生活。\\\\n【章法與結構】前半段以三個「不...」的排比句（不昧己心、不拂人情、不竭物力），分別從對己、對人、對物三個維度提出修養的準則。後半段再以三個「為...」的排比句（為天地...、為生民...、為子孫...）呼應，層次分明，氣勢恢宏。\\\\n【思想與義理】這是一段融合了儒家倫理與自然生態保育觀唸的箴言。對己要誠實不欺（道德涵養），對人要體貼通達（社會和諧），對物要節儉愛惜（永續發展）。作者將個人的日常修為與張載的宏大理想相結合，指出只要在生活中實踐這三點，便是達到了極高的境界，不僅能立身處世，更能造福後世。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-13","chapterId":"cai-gen-tan_ch-5","order":13,"canonicalText":"居官有二語曰：「惟公則生明，惟廉則生威」。居家有二語曰：「惟恕則平情，惟儉則足用」。","sentenceIds":["cai-gen-tan_ch-5_p-13_s-1","cai-gen-tan_ch-5_p-13_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做官有兩句格言說：「只有公正才能產生明察，只有廉潔才能產生威信。」居家生活有兩句格言說：「只有寬恕才能平息情緒、使心境平和，只有節儉才能使財用充足。」","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 305 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「居官有二語曰惟公則生明惟廉則生威居家有二……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「居」、「官」、「有」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-13）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-14","chapterId":"cai-gen-tan_ch-5","order":14,"canonicalText":"處富貴之地，要知貧賤的痛癢；當少壯之時，須念衰老的辛酸。","sentenceIds":["cai-gen-tan_ch-5_p-14_s-1","cai-gen-tan_ch-5_p-14_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"身處富貴顯赫的地位，要能體會貧困卑微者的痛苦與疾苦；正值年輕力壯的時候，應當想到衰老體衰時的艱難與辛酸。","analysis":"【主題與背景】本條倡導「設身處地」與「居安思危」的思想。富貴與貧賤、少壯與衰老，皆為人生對立之兩極。\\\\n【詞義與名物】處富貴時易生驕慢，若能體察貧賤者的「痛癢」（即疾苦與需求），便能保持同理心與仁愛之懷；少壯時易揮霍光陰與精力，若能念及衰老之時的無力與無奈，便會懂得珍惜當下、未雨綢繆。\\\\n【思想與篇章】這體現了儒家「己所不欲，勿施於人」的仁恕精神，以及道家對事物盛極必衰規律的清醒認知。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-15","chapterId":"cai-gen-tan_ch-5","order":15,"canonicalText":"持身不可太皎潔，一切污辱垢穢要茹納的；與人不可太分明，一切善惡賢愚要包容的。","sentenceIds":["cai-gen-tan_ch-5_p-15_s-1","cai-gen-tan_ch-5_p-15_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"立身處世不能過於潔癖、清高，對於世俗中的一切委屈、侮辱與汙穢，要能容忍吸納；與人交往不可分得太清界限，對於世間各種善惡、賢愚之人，都要有所包容。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 307 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「持身不可太皎潔一切污辱垢穢要茹納的與人不……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「持」、「身」、「不」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-15）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-16","chapterId":"cai-gen-tan_ch-5","order":16,"canonicalText":"休與小人仇讎，小人自有對頭；休向君子諂媚，君子原無私惠。","sentenceIds":["cai-gen-tan_ch-5_p-16_s-1","cai-gen-tan_ch-5_p-16_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不要與小人結下仇怨，小人自然會有與他爭鬥的對手；不要向君子逢迎諂媚，君子本來就不會因為私情而給予他人恩惠。","analysis":"【主題與背景】本條提示對待君子與小人的處世智慧。小人行事往往出於私利，氣量狹小，若與之結怨，必招致無謂的糾纏與報復，況且小人好利爭鬥，自然會有其他利益衝突者（即其「對頭」）去牽制他，故不必親自與之爭鋒。\\\\n【詞義與名物】君子行事則以道義為準則，講求大公無私，絕不會因為他人的諂媚阿諛而給予徇私的利益，因此迎合諂媚君子不僅無益，反而自貶人格。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-17","chapterId":"cai-gen-tan_ch-5","order":17,"canonicalText":"磨［石厲］當如百煉之金，急就者非邃養施為宜。似千鈞之弩，輕發者無宏功。","sentenceIds":["cai-gen-tan_ch-5_p-17_s-1","cai-gen-tan_ch-5_p-17_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"自我磨礪應當像提煉黃金一樣，經過百般錘煉，急於求成的人不適合深厚的修養與大有作為的施展；磨礪心志也應如同拉開千鈞重的強弩，輕易發射的箭很難建立宏偉的功業。","analysis":"【主題與背景】本條說明修身與建功立業皆需沉潛與積累。「磨礪」如同煉金，必須經過無數次的鍛造才能去粗取精，成大器者必定經過長期「邃養」（深厚的涵養與積累），急功近利者只求速成，其根基必不穩固。\\\\n【詞義與名物】「千鈞之弩」比喻積蓄了巨大力量的器識與志向，若輕易發射（急於表現、輕率行動），則無法在關鍵時刻發揮決定性的作用。\\\\n【思想與篇章】這與儒家「欲速則不達」及道家「大器晚成」的道理相契合。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-18","chapterId":"cai-gen-tan_ch-5","order":18,"canonicalText":"建功立業者，多虛圓之士；僨事失機者，必執拗之人。","sentenceIds":["cai-gen-tan_ch-5_p-18_s-1","cai-gen-tan_ch-5_p-18_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"能夠建立豐功偉業的人，多半是處事靈活圓融、懂得變通的人；而把事情搞砸、錯失良機的人，必定是性格固執、不聽勸告的人。","analysis":"【訓詁與名物】「建功立業」指建立功勳與事業。「虛圓」指虛心且圓融，懂得變通而不死板。「僨事」指敗事、把事情弄糟。「失機」指錯失機會。「執拗」指固執己見、不肯變通。\\\\n【章法與結構】這是一個非常精煉的對偶句。「建功立業者」對「僨事失機者」，「多虛圓之士」對「必執拗之人」。一成一敗，一圓一拗，以鮮明的對比手法，道出了為人處世的成敗關鍵。\\\\n【思想與義理】此段點出了性格決定命運的道理。在複雜的社會中，能夠成就大業者，往往具備「虛」以容人、「圓」以應變的智慧，他們不僵化執著，能審時度勢。相反地，失敗者往往因為太過自我中心，固執己見，聽不進別人的意見，最終導致錯失良機而敗事。這並非鼓勵圓滑世故，而是強調在堅持原則之下，處事應具備的靈活性與包容力。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-19","chapterId":"cai-gen-tan_ch-5","order":19,"canonicalText":"儉，美德也，過則為慳吝、為鄙嗇，反傷雅道；讓，懿行也，過則為足恭、為曲禮，多出機心。","sentenceIds":["cai-gen-tan_ch-5_p-19_s-1","cai-gen-tan_ch-5_p-19_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"節儉本是美好的品德，但如果過分了就會變成小氣與刻薄，反而傷害了高雅的處世之道；謙讓本是高尚的品行，但如果過分了就會變成諂媚奉迎、虛偽客套，這大多是出於投機取巧的心計。","analysis":"【主題與背景】本條從中庸之道出發，警惕美德的過度與變質。節儉（儉）與謙讓（讓）雖為儒家所推崇，但凡事過猶不及。\\\\n【詞義與名物】過度的節儉流於「慳吝」與「鄙嗇」，失去了人情味與體面；過度的謙讓則淪為虛偽的「足恭」（過分恭敬）與「曲禮」（扭曲的禮節），反而顯露出背後的利益企圖（機心）。\\\\n【思想與篇章】這呼應了《論語》中「禮，與其奢也，寧儉；喪，與其易也，寧戚」以及反對虛偽禮貌的思想，強調品德應以真誠與適度為本。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-20","chapterId":"cai-gen-tan_ch-5","order":20,"canonicalText":"毋憂拂意，毋喜快心，毋恃久安，毋憚初難。","sentenceIds":["cai-gen-tan_ch-5_p-20_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不要為不如意的事情而憂愁，不要為一時的稱心如意而過分歡喜，不要依恃長期的平安而放鬆警惕，不要害怕剛開始時遇到的困難。","analysis":"【主題與背景】本條包含四個「毋」，指導修持心境、應對人生起伏的原則。前兩句「毋憂拂意，毋喜快心」強調心境的平衡，不為外在的順逆境遇所動搖（近於佛教的「無執」與道家的「齊物」）；後兩句「毋恃久安，毋憚初難」則著眼於行動，指出安逸易使人怠惰、首創易使人畏縮，故應警惕安樂中的隱患，並勇於面對起步時的艱難。\\\\n【詞義與名物】這是一套極具實用價值的心理調節法則。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-21","chapterId":"cai-gen-tan_ch-5","order":21,"canonicalText":"飲宴之樂多，不是個好人家。聲華之習勝，不是個好士子。名位之念重，不是個好臣工。","sentenceIds":["cai-gen-tan_ch-5_p-21_s-1","cai-gen-tan_ch-5_p-21_s-2","cai-gen-tan_ch-5_p-21_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"經常沉溺於飲酒宴會之樂的，絕不是一個風氣良好的家庭。過度追求聲色浮華之氣息的，絕不是一個有品德的讀書人。把功名地位看得太重的，絕不是一個盡忠職守的好官員。","analysis":"【訓詁與名物】「飲宴」指喝酒聚餐。「人家」指家庭。「聲華」指聲色犬馬與浮華不實的風氣。「習」指習慣、風氣。「勝」指過盛、強烈。「士子」指讀書人、知識份子。「名位」指名聲與官位。「臣工」指朝廷的臣子、官員。\\\\n【章法與結構】全段由三個結構完全相同的句子組成排比：「...多（勝、重），不是個好...」。分別從家庭、讀書人、官員三個不同的社會角色進行批判，句法整齊劃一，語氣嚴厲而肯定。\\\\n【思想與義理】這段文字提出了對不同社會角色的基本道德要求。家庭應以勤儉持家，若沉溺於宴樂，必致家道中落；讀書人應以修身治學為本，若沾染浮華，必喪失氣節與學問；官員應以國計民生為念，若太重名利，必導致貪污腐敗。作者從細微的風氣與念頭入手，一針見血地指出了敗家、敗身、敗國的根源，警惕世人應堅守本分，戒除浮華與貪念。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-22","chapterId":"cai-gen-tan_ch-5","order":22,"canonicalText":"仁人心地寬舒，便福厚而慶長，事事成個寬舒氣象；鄙夫念頭迫促，便祿薄而澤短，事事成個迫促規模。","sentenceIds":["cai-gen-tan_ch-5_p-22_s-1","cai-gen-tan_ch-5_p-22_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"有仁德的人心胸寬廣舒暢，因此福澤深厚而吉慶綿長，做任何事都呈現出寬宏舒暢的氣象；庸俗卑微的小人心胸狹隘急躁，因此祿位微薄而恩澤短暫，做任何事都顯得侷促小氣。","analysis":"【主題與背景】本條對比「仁人」與「鄙夫」的心胸氣量及其帶來的命運。「寬舒」是仁者之相，心寬則不計較一時得失，能容人容物，自然能積累福報、行事從容；「迫促」則是鄙夫之態，斤斤計較、目光短淺，為名利所役使，這導致其行事侷促，福澤自然短淺。\\\\n【詞義與名物】這與儒家「仁者壽」、「君子坦蕩蕩，小人長慼慼」的思想一脈相承，說明心態決定氣度，氣度決定格局與命運。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-23","chapterId":"cai-gen-tan_ch-5","order":23,"canonicalText":"用人不宜刻，刻則思效者去；交友不宜濫，濫則貢諛者來。","sentenceIds":["cai-gen-tan_ch-5_p-23_s-1","cai-gen-tan_ch-5_p-23_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"任用人才不應當過於嚴苛，如果太過嚴苛，想要前來效力的人就會離去；結交朋友不應當過於雜亂，如果交往太濫，阿諛奉承的人就會趁虛而入。","analysis":"【主題與背景】本條指出用人與交友的分寸。「用人不宜刻」強調寬以待下，若對下屬百般挑剔、刻薄寡恩，縱有忠義之士也難以留存；「交友不宜濫」強調擇友須慎，若無原則地廣泛結交，身邊必然會聚集許多投其所好、阿諛奉承的諂媚之徒。\\\\n【詞義與名物】這體現了儒家知人善任、擇友以正的原則，強調「寬以得人」與「慎交諍友」的重要性。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-24","chapterId":"cai-gen-tan_ch-5","order":24,"canonicalText":"大人不可不畏，畏大人則無放逸之心；小民亦不可不畏，畏小民則無豪橫之名。","sentenceIds":["cai-gen-tan_ch-5_p-24_s-1","cai-gen-tan_ch-5_p-24_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對於有德有位的主管、長輩或賢者，不可不心存敬畏，敬畏他們就能剋制自己，不產生放蕩懈怠的心思；對於普通的平民百姓，也同樣不可不存敬畏之心，敬畏平民百姓就不會落得仗勢欺人、蠻橫無理的名聲。","analysis":"【主題與背景】本條探討「敬畏」在修身與處世中的作用。畏「大人」（指有德行的長者或居高位者），是為了藉由外在的道德威嚴來約束自身，防止自我膨脹與放縱逸樂（即「君子有三畏，畏天命，畏大人，畏聖人之言」）；畏「小民」（指基層百姓），則是體現了民本思想與謙遜態度。\\\\n【詞義與名物】百姓的輿論與向背決定了為政者成敗，不輕視弱小、敬畏民意，才能避免專橫跋扈，保持清正的名聲。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-25","chapterId":"cai-gen-tan_ch-5","order":25,"canonicalText":"事稍拂逆，便思不如我的人，則怨尤自消；心稍怠荒，便思勝似我的人，則精神自奮。","sentenceIds":["cai-gen-tan_ch-5_p-25_s-1","cai-gen-tan_ch-5_p-25_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到事情稍微有些不順心的時候，就去想想那些處境還不如自己的人，那麼心中的怨恨與不滿自然就會消除；當內心稍微感到懈怠荒廢的時候，就去想想那些成就勝過自己的人，那麼精神自然就會振奮起來。","analysis":"【訓詁與名物】「拂逆」指違背心意、不順利。「怨尤」指怨恨、責怪。「怠荒」指懈怠、荒廢不振。「奮」指振作、奮發。【章法與結構】本段由兩組對稱的假設複句構成。「事稍拂逆」對應「心稍怠荒」，「思不如我的人」對應「思勝似我的人」，「怨尤自消」對應「精神自奮」。句式工整，節奏明快，透過正反兩種情境與兩種參照物的對比，提出了極具操作性的心理調節法。【思想與義理】此句展現了儒家「反求諸己」的修養功夫與高超的心理調適智慧。人性的弱點在於順境易驕怠，逆境易怨天尤人。作者教導我們運用「比下有餘，比上不足」的思維方式：在挫折中向下看以知足感恩，在懈怠時向上看以激發鬥志。這是一種能使人始終保持心理平衡與前進動力的中庸之道。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-26","chapterId":"cai-gen-tan_ch-5","order":26,"canonicalText":"不可乘喜而輕諾，不可因醉而生［目真］，不可乘快而多事，不可因倦而鮮終。","sentenceIds":["cai-gen-tan_ch-5_p-26_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不可以趁著高興就輕易向別人許下諾言，不可以因為喝醉了酒就隨便發脾氣，不可以趁著一時痛快就去多管閒事，不可以因為感到疲倦就做事情有始無終。","analysis":"【訓詁與名物】「乘喜」指趁著高興的時候。「輕諾」指輕易答應別人。「［目真］」即「瞋」，發怒時睜大眼睛，此指發脾氣、動怒。「乘快」指圖一時痛快。「鮮終」指很少有好的結果，或做事有始無終，鮮音ㄒㄧㄢˇ，少。【章法與結構】本段連用四個「不可...而...」的排比句式，句式極其嚴整。每一句都點出了一種特殊的情境（喜、醉、快、倦）以及在這種情境下容易犯的過失（輕諾、生瞋、多事、鮮終），語氣堅定，充滿告誡意味。【思想與義理】這段話旨在強調「持重」與「自制」的修身原則。人在情緒高漲（喜、快）、理智減弱（醉）或身心疲憊（倦）時，最容易失去理智，做出草率或半途而廢的決定。「輕諾必寡信」，「多事多患」。作者提醒我們，越是在這種非常態的時刻，越需要強大的自制力來約束言行，保持冷靜與慎重，才能避免日後的後悔與災禍。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-27","chapterId":"cai-gen-tan_ch-5","order":27,"canonicalText":"釣水，逸事也，尚持生殺之柄；弈棋，清戲也，且動戰爭之心。可見喜事不如省事之為適，多能不如無能之全真。","sentenceIds":["cai-gen-tan_ch-5_p-27_s-1","cai-gen-tan_ch-5_p-27_s-2","cai-gen-tan_ch-5_p-27_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"垂釣本是一件閒適安逸的事，卻依然掌握著魚兒的生殺大權；下棋本是一種高雅清閒的遊戲，卻依然動用了爭強好勝的戰爭心思。由此可見，喜歡多事不如省事來得舒適安逸，多才多藝不如看似無能那樣能保全純真本性。","analysis":"【主題與背景】本條從垂釣與下棋這兩件雅事切入，剖析人類爭鬥與掌控欲的無處不在。即使在最閒適、清雅的活動中，人也往往不自覺地展現出對生命的支配欲（釣魚）和競爭心（弈棋），這反而違背了休閒的初衷。\\\\n【詞義與名物】因此，作者得出道家式的結論：「省事」勝於「喜事」（多事），「無能」（保持質樸、不露鋒芒）勝於「多能」（被才藝所累，追逐外物）。\\\\n【思想與篇章】這呼應了莊子「不以物易己」以及老子「大巧若拙」的思想，強調返璞歸真。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-28","chapterId":"cai-gen-tan_ch-5","order":28,"canonicalText":"聽靜夜之鐘聲，喚醒夢中之夢；觀澄潭之月影，窺見身外之身。","sentenceIds":["cai-gen-tan_ch-5_p-28_s-1","cai-gen-tan_ch-5_p-28_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"聆聽寧靜深夜裡傳來的鐘聲，能夠喚醒紅塵俗世這場夢境中的迷夢；觀察澄澈池潭裡倒映的月影，能夠窺見肉體凡胎之外那永恆空靈的真我。","analysis":"【主題與背景】本條充滿禪宗的空靈與悟境。「夢中之夢」意指世人將虛幻的現實生活視為真實，在其中爭名奪利，猶如夢中作夢；夜半鐘聲（常指寺廟鐘聲）清脆悠遠，能震人心魄，讓人猛然省悟世事之虛幻。\\\\n【詞義與名物】「身外之身」借用澄潭月影的比喻，月非潭水，水非月影，但影由月生，以此暗示在短暫的肉體軀殼之外，還有一個清凈不染的本自具足之佛性（真我）。\\\\n【思想與篇章】此句通過自然與聲音的感悟，引導讀者進行深度的自我覺察。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-29","chapterId":"cai-gen-tan_ch-5","order":29,"canonicalText":"鳥語蟲聲，總是傳心之訣；花英草色，無非見道之文。學者要天機清徹，胸次玲瓏，觸物皆有會心處。","sentenceIds":["cai-gen-tan_ch-5_p-29_s-1","cai-gen-tan_ch-5_p-29_s-2","cai-gen-tan_ch-5_p-29_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心志如果過於狹隘執著，往往是處於貪慾與偏執之境；若能放下私心雜念，自然心明眼亮、坦蕩曠達。學習修身的人務必要理清心靈的幹擾，凡事順應自然的本真狀態。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 321 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「鳥語蟲聲總是傳心之訣花英草色無非見道之文……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「鳥」、「語」、「蟲」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-29）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-30","chapterId":"cai-gen-tan_ch-5","order":30,"canonicalText":"人解讀有字書，不解讀無字書；知彈有絃琴，不知彈無絃琴。以跡用不以神用，何以得琴書佳趣？","sentenceIds":["cai-gen-tan_ch-5_p-30_s-1","cai-gen-tan_ch-5_p-30_s-2","cai-gen-tan_ch-5_p-30_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人們只懂得閱讀有文字的書本，卻不懂得閱讀天地自然這本無字之書；人們只知道彈奏有琴絃的古琴，卻不知道去彈奏心中無弦的自然之琴。如果僅在有形的痕跡上加以尋求、而不從無形的精神神韻去領悟，又怎麼能得到琴書之中真正的妙趣呢？","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 322 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「人解讀有字書不解讀無字書知彈有絃琴不知彈……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「人」、「解」、「讀」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-30）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-31","chapterId":"cai-gen-tan_ch-5","order":31,"canonicalText":"山河大地已屬微塵，而況塵中之塵！血肉身驅且歸泡影，而況影外之影！非上上智，無了了心。","sentenceIds":["cai-gen-tan_ch-5_p-31_s-1","cai-gen-tan_ch-5_p-31_s-2","cai-gen-tan_ch-5_p-31_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遼闊的江河與廣袤的大地，在茫茫宇宙中已渺小得如同微塵，更何況是微塵之中的微塵（指人類與其爭奪的名利）呢！短暫的血肉之軀最終也將歸於幻滅的泡影，更何況是泡影之外的影子（指身後的名聲與虛榮）呢！若不是具備極高的智慧，就不會有徹底看穿這一切的明淨心境。","analysis":"【主題與背景】本條蘊含佛教的宇宙觀與空觀（特別是《金剛經》「一切有為法，如夢幻泡影」之意）。從宏觀的宇宙尺度看，山河大地不過是一粒微塵，人在其中爭奪的得失更是微不足道；從時間的尺度看，人的生命如泡影般短暫，而附著於生命之上的功名利祿更是影子的影子（「影外之影」），虛無縹緲。\\\\n【詞義與名物】唯有「上上智」（最透徹的智慧）才能產生「了了心」（徹底明瞭、毫無執著的心），從而從世俗的煩惱中解脫出來。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-32","chapterId":"cai-gen-tan_ch-5","order":32,"canonicalText":"石火光中，爭長兢短，幾何光陰？蝸牛角上，較雌論雄，許大世界？","sentenceIds":["cai-gen-tan_ch-5_p-32_s-1","cai-gen-tan_ch-5_p-32_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在像擊石發出的一閃即逝的火光中，去爭奪高低與長短，能有多少光陰？在像蝸牛角那樣微小的空間裡，去比較雌雄與勝負，能有多大的世界？","analysis":"【主題與背景】本條運用了極具衝擊力的比喻來棒喝世俗的爭鬥。「石火光中」比喻人生的短暫，語出佛教與道家文學；「蝸牛角上」典出《莊子·則陽》，指戴晉人以蝸牛角上的兩個國家爭地大戰來勸誡魏王，比喻空間的狹隘與爭鬥的無謂。\\\\n【詞義與名物】在時空的無限坐標系中，人類為了微小的利益而爾輿我詐，顯得極其滑稽與渺小。\\\\n【思想與篇章】此條旨在勸人放寬眼界，超脫於世俗的蠅頭小利與意氣之爭。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-33","chapterId":"cai-gen-tan_ch-5","order":33,"canonicalText":"有浮雲富貴之風，而不必巖棲穴處；無膏盲泉石之癖，而常自醉酒耽詩。兢逐聽人而不嫌盡醉，恬［心詹］適己而不誇獨醒，此釋氏所謂不為法纏、不為空纏，身心兩自在者。","sentenceIds":["cai-gen-tan_ch-5_p-33_s-1","cai-gen-tan_ch-5_p-33_s-2","cai-gen-tan_ch-5_p-33_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"擁有視富貴如浮雲的清高風骨，卻不必非要隱居在深山洞穴之中；沒有把熱愛山水當作無可救藥的怪癖，卻也能經常飲酒作詩自得其樂。任憑旁人去競爭追逐而不反對與他們一同沉醉，保持內心的恬靜安適卻也不誇耀自己獨自清醒，這就是佛家所說的既不被世俗法則所束縛、也不被空無境界所束縛，達到了身心都無比自在的境界。","analysis":"【主題與背景】本條提倡一種不落兩邊的中道隱逸觀。真正的解脫不是流於形式的「巖棲穴處」或執著於山水美景的「膏肓之癖」（這依然是一種執著，即「法纏」），也不是一味排斥世俗、孤芳自賞（即執著於空、誇耀獨醒，是為「空纏」）。\\\\n【詞義與名物】真正的自在是身處世俗而心不染塵，能與世俗和光同塵而不隨波逐流，實現「心無罣礙」的圓融狀態。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-34","chapterId":"cai-gen-tan_ch-5","order":34,"canonicalText":"延促由於一念，寬窄係之寸心。故機閑者一日遙於千古，意寬者斗室廣於兩間。","sentenceIds":["cai-gen-tan_ch-5_p-34_s-1","cai-gen-tan_ch-5_p-34_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"時間的漫長與短暫取決於人的一念之間，空間的寬敞與狹窄關乎於人的方寸之心。因此，心境悠閒的人，過上一天比千秋萬代還要悠長；胸懷寬廣的人，即使身處窄小的斗室，也覺得它比天地之間還要遼闊。","analysis":"【主題與背景】本條闡述唯心所現、境隨心轉的道理。時間的「延促」（拉長與縮短）和空間的「寬窄」並非絕對的物理概念，而是主觀的心靈感受。\\\\n【詞義與名物】心中若無俗務牽絆，心定神閒（機閑），便能體會「一日遙於千古」的深邃；心胸如果開闊，沒有私欲與得失的逼迫，即便是狹小的「斗室」，在精神上也能如天地（兩間，指天地之間）般無垠。\\\\n【思想與篇章】這與莊子逍遙遊的精神以及佛教的唯心造思想高度一致。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-35","chapterId":"cai-gen-tan_ch-5","order":35,"canonicalText":"都來眼前事，知足者仙境，不知足者凡境；總出世上因，善用者生機，不善用者殺機。","sentenceIds":["cai-gen-tan_ch-5_p-35_s-1","cai-gen-tan_ch-5_p-35_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"歸結眼前所遇到的種種事情，知足的人會覺得處處都是天堂仙境，不知足的人則覺得處處都是痛苦的凡塵俗境；總結世間一切因緣遭際，善於利用的人能將其化為蓬勃的生機，不善於利用的人則會將其變成毀滅的殺機。","analysis":"【主題與背景】本條強調心態對人生境遇的決定性作用。「知足者仙境，不知足者凡境」說明幸福不在於外在物質的多寡，而在於內心的滿足感，知足則當下即是解脫；「善用者生機，不善用者殺機」則指出世間的際遇（如挫折、名利、權力等）本身是中性的，若能以智慧引導，挫折可成磨礪之助（生機），若執迷不悟，富貴亦可招致禍端（殺機）。\\\\n【詞義與名物】這體現了佛道兩家轉識成智、善護心念的思想。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-36","chapterId":"cai-gen-tan_ch-5","order":36,"canonicalText":"趨炎附勢之禍，甚慘亦甚速；棲恬守逸之味，最淡亦最長。","sentenceIds":["cai-gen-tan_ch-5_p-36_s-1","cai-gen-tan_ch-5_p-36_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"攀附權貴、巴結有勢力者的災禍，往往非常悽慘而且來得極快；安於恬靜、堅守閒適生活的趣味，雖然最為清淡，卻也最為持久悠長。","analysis":"【主題與背景】本條對比「趨炎附勢」與「棲恬守逸」的結局。追求世俗的名利權勢（趨炎附勢）如同飛蛾撲火，權力場上的更迭與傾軋瞬息萬變，一旦失勢，招致的災禍往往毀滅性且迅速；相反，遠離名利場，過著平淡、寧靜的生活（棲恬守逸），雖然物質與名聲清淡，但遠離了紛爭，能長久保全自身與內心的平靜。\\\\n【詞義與名物】這反映了道家「淡泊明志」、「柔弱勝剛強」的生存智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-37","chapterId":"cai-gen-tan_ch-5","order":37,"canonicalText":"色慾火熾，而一念及病時，便興似寒灰；名利飴甘，而一想到死地，便味如咀蠟。故人常憂死慮病，亦可消幻業而長道心。","sentenceIds":["cai-gen-tan_ch-5_p-37_s-1","cai-gen-tan_ch-5_p-37_s-2","cai-gen-tan_ch-5_p-37_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當對女色的慾望如烈火般熾盛時，只要一想到生病時的痛苦，慾火便會像冷卻的灰燼一樣平息；當覺得名利像糖一樣甜美時，只要一想到死亡的境地，就會覺得名利像嚼蠟一樣索然無味。因此，人如果能經常憂慮死亡、思慮疾病，也可以消除虛幻的業障而增長向道的修行之心。","analysis":"【訓詁與名物】「火熾」形容火勢猛烈，比喻慾望強烈。「寒灰」指冷卻的灰燼，比喻心灰意冷。「飴甘」指像糖漿一樣甜美。「咀蠟」指嚼蠟，比喻毫無味道。「幻業」指由虛幻不實的慾望所造下的罪業。「道心」指追求真理、超越世俗的心境。【章法與結構】本段前半部採用對偶句，將「色慾」與「名利」這兩大世俗誘惑並舉，並分別以「病」與「死」作為對治的藥方，運用「似寒灰」與「味如咀蠟」的生動比喻，形成強烈的反差。後半部則以「故」字作結，總結出「憂死慮病」的修行價值，邏輯嚴密。【思想與義理】這段話深受佛教與道家思想的影響，提出了「以死觀生」的獨特視角。色與名利是世人難以擺脫的誘惑，但若將其置於生老病死的終極視角下審視，其虛幻與短暫便暴露無遺。作者認為，適度地直面病痛與死亡，並非悲觀厭世，反而是一種強大的清醒劑，能幫助我們勘破紅塵，放下執著，回歸精神的純淨與超脫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-38","chapterId":"cai-gen-tan_ch-5","order":38,"canonicalText":"爭先的徑路窄，退後一步自寬平一步；濃艷的滋味短，清淡一分自悠長一分。","sentenceIds":["cai-gen-tan_ch-5_p-38_s-1","cai-gen-tan_ch-5_p-38_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"爭奪領先的道路非常狹窄，如果能主動退後一步，道路自然會寬闊平坦一步；濃鬱艷麗的滋味非常短暫，如果能保持清淡一分，趣味自然會悠長一分。","analysis":"【主題與背景】本條以路寬窄與味濃淡為喻，勸誡世人退讓與平淡的妙處。「爭先」如同千軍萬馬過獨木橋，必然擁擠且充滿衝突，而「退後一步」則海闊天空，既避開了鋒芒，也給了自己迴旋的餘地；「濃艷」之物（如感官刺激、奢華享樂）容易讓人審美疲勞且難以持久，唯有「清淡」之美（如平淡的生活、真摯的琴書之樂）才能經得起時間的洗禮。\\\\n【詞義與名物】此語融合了老子的「不敢為天下先」與「淡乎其無味」的思想。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-39","chapterId":"cai-gen-tan_ch-5","order":39,"canonicalText":"隱逸林中無榮辱，道義路上泯炎涼。進步處便思退步，庶免觸藩之禍。著手時光圖放手，纔脫騎虎之危。","sentenceIds":["cai-gen-tan_ch-5_p-39_s-1","cai-gen-tan_ch-5_p-39_s-2","cai-gen-tan_ch-5_p-39_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"隱居在山林之中，就沒有世俗的榮耀與屈辱；行走在追求道義的道路上，就能消除人情世態的炎涼感。在順境中向前進步時，就要考慮到日後退步的後路，這樣或許就能避免像羊角卡在藩籬中那樣進退兩難的災禍；在剛開始著手做一件事時，就要謀劃好將來如何放手，這樣才能脫離騎虎難下的危險。","analysis":"【訓詁與名物】「隱逸林中」指退隱山林。「泯炎涼」指消除、忘卻世間的人情冷暖。「觸藩之禍」典出《易經·大壯卦》「羝羊觸藩，羸其角」，比喻像公羊用角去頂籬笆，結果角被卡住，進退兩難。「著手」指開始做。「騎虎之危」比喻事情中途遇到困難，但又無法停止下來的危險處境。【章法與結構】本段由兩組對偶句構成。前兩句描繪了超越世俗名利後的精神自由境界（「無榮辱」、「泯炎涼」）；後兩句則轉入具體的處世策略，強調在「進步」時思「退步」，在「著手」時圖「放手」，並用「觸藩」與「騎虎」兩個生動的典故來強調缺乏遠見的後果，理趣盎然。【思想與義理】此段蘊含了道家功成身退的哲理與《易經》中防患未然的憂患意識。人生的悲劇往往源於貪戀權位與不懂得適可而止。作者教導我們在順境與開創之初，就必須具備抽身而退的智慧。只有看破榮辱炎涼，並在行動中保持清醒的退場機制，才能在複雜的世事中保全自身，遊刃大餘。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-40","chapterId":"cai-gen-tan_ch-5","order":40,"canonicalText":"貪得者分金恨不得玉，封公怨不授侯，權豪自甘乞丐；知足者藜羹旨於膏梁，布袍暖於狐貉，編民不讓王公。","sentenceIds":["cai-gen-tan_ch-5_p-40_s-1","cai-gen-tan_ch-5_p-40_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"貪得無厭的人分到了黃金還遺憾沒有得到美玉，封了公爵還怨恨沒有授給侯爵，這種人雖然身處權貴富豪之位，卻自己甘願作精神上的乞丐；知足常樂的人喫粗茶淡飯也覺得比山珍海味還要美味，穿粗布衣服也覺得比狐貉皮衣還要溫暖，他們雖是普通老百姓，但精神上的富足不輸給王公貴族。","analysis":"【主題與背景】本條生動對比了貪婪與知足在精神層面造成的貧富逆轉。「權豪自甘乞丐」深刻揭示了物質富足而精神貧困的荒謬現象，貪得無厭者永遠處於匱乏與焦慮中，本質上與乞丐無異；「編民不讓王公」則讚美了精神獨立與知足者的高貴，普通的平民（編民）若能安貧樂道，其內心的寧靜與快樂，連擁有天下的王公也無法企及。\\\\n【詞義與名物】這高度契合孔子「賢哉回也」的安貧樂道精神與老子「知足者富」的哲學。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-41","chapterId":"cai-gen-tan_ch-5","order":41,"canonicalText":"矜名不如逃名趣，練事何如省事閒。孤雲出岫，去留一無所係；朗鏡懸空，靜躁兩不相干。","sentenceIds":["cai-gen-tan_ch-5_p-41_s-1","cai-gen-tan_ch-5_p-41_s-2","cai-gen-tan_ch-5_p-41_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"誇耀名聲不如躲避名聲來得有趣，精明練達於世俗事務何如減少事端來得清閒。像一片孤單的雲朵飄出山谷，去留都沒有任何牽掛；像一面明亮的鏡子高懸在空中，無論外界是安靜還是喧鬧，都與它毫不相干。","analysis":"【主題與背景】本條倡導超脫名利、保持心靈自由。「矜名」是執著於虛榮，「逃名」則是擺脫名譽的束縛，重獲精神自由；「練事」雖是能力，但終究在塵俗中勞神，不及「省事」能讓人心境清閒。\\\\n【詞義與名物】後半句以「孤雲出岫」（典出陶淵明《歸去來兮辭》）比喻無心、無礙的自在狀態；以「朗鏡懸空」比喻心境的客觀與澄明，外界的「靜躁」紛擾只在鏡中呈現，卻無法污染鏡子本身。\\\\n【思想與篇章】這展現了佛家「物來則應，過去不留」與道家無為而治的境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-42","chapterId":"cai-gen-tan_ch-5","order":42,"canonicalText":"山林是勝地，一營戀便成市朝；書畫是雅事，一貪癡便成商賈。蓋心無染著，俗境是仙都；心有絲牽，樂境成悲地。","sentenceIds":["cai-gen-tan_ch-5_p-42_s-1","cai-gen-tan_ch-5_p-42_s-2","cai-gen-tan_ch-5_p-42_s-3","cai-gen-tan_ch-5_p-42_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"山林本來是風景優美的隱居勝地，但如果心裡一有營求眷戀之念，這裡就變成了喧鬧的朝廷與市集；賞玩書畫本來是高雅的情韻韻事，但如果一有貪婪癡迷之念，這種行為就變得像唯利是圖的商人一樣。所以說，只要內心沒有被世俗的欲望所沾染，即使身處凡俗的環境，也如同身在神仙居住的都城；如果內心被各種私慾所牽絆，即使身處快樂的境地，也會變成悲哀的所在。","analysis":"【訓詁與名物】「營戀」指營求算計、眷戀不捨。「市朝」指市集與朝廷，代指名利追逐的喧囂之地。「貪癡」指貪婪與癡迷。「商賈」指商人，古代行商稱商，坐商稱賈。「染著」指沾染執著。「仙都」指神仙居住的清淨之地。「絲牽」比喻內心被欲望或俗念牽絆。【章法與結構】本段前兩句以「...是...，一...便成...」的句式，舉出「山林」與「書畫」兩個具體例子，說明外外事物會因心境改變而變質。最後一句則以「蓋」字總括，用「心無染著」與「心有絲牽」的正反對比，點出「境由心造」的核心主旨。由事入理，說服力極強。【思想與義理】這段話是典型的心學與禪宗思想的體現。它打破了世俗對於「雅與俗」、「出世與入世」在空間和事物上的刻板界線。真正的清雅與解脫不在於身處山林或把玩書畫，而在於內心的清淨無為。如果心存貪念，山林也是名利場；如果心無掛礙，喧囂鬧市亦是清淨仙鄉。萬法唯心造，心態決定了人生的境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-43","chapterId":"cai-gen-tan_ch-5","order":43,"canonicalText":"時當喧雜，則平日所記憶者皆漫然忘去；境在清寧，則夙昔所遺忘者又恍爾現前。可見靜躁稍分，昏明頓異也。","sentenceIds":["cai-gen-tan_ch-5_p-43_s-1","cai-gen-tan_ch-5_p-43_s-2","cai-gen-tan_ch-5_p-43_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當身處喧囂雜亂的環境時，平日裡用心記憶的事物往往會不由自主地忘得一乾二淨；而當身處清靜安寧的環境時，從前早已經遺忘的往事卻又會忽然清晰地浮現在眼前。由此可見，內心的安靜與浮躁只要有稍微的差異，頭腦的昏沉與清明就會立刻產生截然不同的結果。","analysis":"【訓詁與名物】「喧雜」指環境喧鬧、聲音嘈雜，也暗指內心受外界幹擾而浮躁。「漫然」意為隨意地、不經意地，這裡指不由自主。「夙昔」指從前、往昔。「恍爾」即恍然、忽然，形容事物突然清晰顯現的樣子。「靜躁」指安靜與浮躁兩種心境。「稍分」意為只有稍微的分野或差別。「昏明」指心智的昏沉迷亂與清明澄澈。「頓異」意為立刻出現巨大的差異。\\\\n【章法與結構】此段以對比手法展開，前兩句是情境的對比：「喧雜」對「清寧」，「漫然忘去」對「恍爾現前」，生動刻畫了環境與心境的互動關係；最後一句是總結，將「靜/躁」與「昏/明」兩組概念相對應，點明主旨，結構緊湊，語氣肯定。\\\\n【思想與義理】這段話蘊含著深刻的修心哲理，強調「靜」對於保持心智清明的重要性。外在環境的喧囂容易引發內心的浮躁，進而導致心智昏沉、記憶散失；相反，清靜的環境能促使內心沉澱，喚醒潛藏的智慧與記憶。這啟示我們，在紛繁複雜的現代社會中，必須學會為自己營造「清寧」的空間與心境，時刻保持內在的平靜，如此方能不被外界所幹擾，保持頭腦的清醒與智慧的洞察力。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-44","chapterId":"cai-gen-tan_ch-5","order":44,"canonicalText":"蘆花被下臥雪眠雲，保全得一窩夜氣；竹葉杯中吟風弄月，躲離了萬丈紅塵。","sentenceIds":["cai-gen-tan_ch-5_p-44_s-1","cai-gen-tan_ch-5_p-44_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"蓋著粗糙的蘆花被子，在白雪與雲霧間安然入睡，能保全得那一股清晨未受汙染的純真元氣；端著竹葉盛裝的酒杯，在清風明月下吟詩作樂，從而遠離了那紛紛擾擾的萬丈紅塵。","analysis":"【主題與背景】本條描繪了一幅極具詩意的隱逸生活圖景。「臥雪眠雲」形容生活簡樸且與自然融為一體；「夜氣」語出《孟子·告子上》，指人在夜間、清晨未與外界接觸時所保有的清明純潔之本性。\\\\n【詞義與名物】在清苦而高潔的隱居生活中，人能保全這份本性不受世俗名利的污染；而「吟風弄月」與「竹葉杯」則代表了不為物役的瀟灑人生態度，是遠離紅塵喧囂的精神避難所。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-45","chapterId":"cai-gen-tan_ch-5","order":45,"canonicalText":"出世之道，即在涉世中，不必絕人以逃世；了心之功即在盡心內，不必絕欲以灰心。","sentenceIds":["cai-gen-tan_ch-5_p-45_s-1","cai-gen-tan_ch-5_p-45_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"超脫凡俗的出世之道，其實就存在於與世俗打交道的涉世過程之中，並不需要斷絕與人的往來以逃避這個世界；明心見性的了心功夫，就存在於盡職盡責的盡心努力之中，並不需要完全斷絕慾望使心境冷若寒灰。","analysis":"【主題與背景】本條批判了消極避世與極端禁慾的觀點，提倡大乘佛教與儒家融合的「在世出世」修行觀。真正的出世修行不是躲進深山、與世隔絕，而是在滾滾紅塵中磨練心性，做到「百花叢中過，片葉不沾身」。\\\\n【詞義與名物】同樣，「了心」也非強行壓制所有欲望、使其「心灰意冷」，而是在履行世俗責任（盡心）的同時，保持內心的超然與覺醒。\\\\n【思想與篇章】這契合了《六祖壇經》中「佛法在世間，不離世間覺」的禪宗智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-46","chapterId":"cai-gen-tan_ch-5","order":46,"canonicalText":"此身常放在閒處，榮辱得失，誰能差遣我？此心常安在靜中，是非利害，誰能瞞昧我？","sentenceIds":["cai-gen-tan_ch-5_p-46_s-1","cai-gen-tan_ch-5_p-46_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果能把這個身體經常安置在閒適、超然的境地，世俗的榮譽、恥辱、得到與失去，又有誰能奴役、支配我呢？如果能把這顆心靈經常安頓在寧靜的狀態中，世間的是非、利害，又有誰能矇騙、迷惑我呢？","analysis":"【主題與背景】本條指出保持身體的「閒」與內心的「靜」是實現精神自由與明察秋毫的關鍵。「身在閒處」使人不捲入無謂的名利爭奪，從而擺脫榮辱得失的牽制，做自己生命的主人；「心在靜中」則如明鏡澄水，外在的是非利害與虛假誘惑便無法蒙蔽（瞞昧）自己的理智。\\\\n【詞義與名物】這體現了道家「無為」以保全自我的智慧，以及儒家「靜虛動直」的修身工夫。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-47","chapterId":"cai-gen-tan_ch-5","order":47,"canonicalText":"我不希榮，何憂乎利祿之香餌；我不兢進，何畏乎仕宦之危機。","sentenceIds":["cai-gen-tan_ch-5_p-47_s-1","cai-gen-tan_ch-5_p-47_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果我不希求世俗的榮華富貴，又有什麼必要去憂慮那些作為誘餌的功名利祿呢？如果我不盲目去競爭升遷，又何必去畏懼官場仕途之中隱藏的危機呢？","analysis":"【主題與背景】本條探討無欲則剛的道理。世人在官場與社會中遭遇種種危機與痛苦，往往是因為心中有對名利權情的渴求，這就如同魚兒看到了「香餌」，雖然知道有鉤，卻依然忍不住吞食，最終受制於人或落入圈套。\\\\n【詞義與名物】若能從根本上斷除對虛榮的奢望（不希榮、不兢進），外在的誘餌便失去效力，仕途的險惡與鬥爭也無法對其構成威脅。\\\\n【思想與篇章】這體現了老子「夫唯不爭，故天下莫能與之爭」的思想。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-48","chapterId":"cai-gen-tan_ch-5","order":48,"canonicalText":"多藏厚亡，故知富不如貧之無慮；高步疾顛，故知貴不如賤之常安。","sentenceIds":["cai-gen-tan_ch-5_p-48_s-1","cai-gen-tan_ch-5_p-48_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"財產財富積累得越多，往往損失得也越慘重，由此可知富貴不如貧窮那樣沒有憂慮；地位站得越高，摔倒跌落時就越快速慘烈，由此可知高貴不如卑微那樣能常保平安。","analysis":"【主題與背景】本條直接化用了道家《老子》的思想。「多藏厚亡」典出《老子》第四十四章「甚愛必大費，多藏必厚亡」，說明過度累積物質財富反而會招致更大的禍患與精神負擔，不如安於簡單生活那般無憂無慮；「高步疾顛」（步子跨得太高、站得太高，摔得越慘）則揭示了權力與地位的脆弱性，居高位者常處於風口浪尖，一旦失勢，身敗名裂，不如平民百姓能安享天年。\\\\n【詞義與名物】這是一種透視利害後的守常、守弱哲學。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-49","chapterId":"cai-gen-tan_ch-5","order":49,"canonicalText":"世上只緣認得「我」字太真，故多種種嗜好、種種煩惱。前人云：「不復知有我，安知物為貴。」又云：「知身不是我，煩惱更何侵。」真破的之言也。","sentenceIds":["cai-gen-tan_ch-5_p-49_s-1","cai-gen-tan_ch-5_p-49_s-2","cai-gen-tan_ch-5_p-49_s-3","cai-gen-tan_ch-5_p-49_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世人只因為把自我（「我」這個概念）看得太空前真實，所以產生了種種對物質的嗜好與種種精神上的煩惱。前人說：「如果不再意識到自我的存在，又怎麼會去珍視外在的物質呢？」又說：「如果懂得這個肉身並非真實的自我，煩惱又怎麼能侵害得到我呢？」這真是切中要害的至理名言啊。","analysis":"【主題與背景】本條從佛教與莊子的「無我」觀出發，剖析人類煩惱的根源。人世間的種種爭奪、痛苦與執著，皆源於「我執」（把「我」當作真實不變的實體，並在此基礎上延伸出「我的財產」、「我的名譽」等）。\\\\n【詞義與名物】引文「不復知有我，安知物為貴」體現了齊物、忘我的道家智慧；「知身不是我，煩惱更何侵」則是佛教「觀身無我」的修行法門。\\\\n【思想與篇章】一旦打破對自我的執著（破我執），一切建立在自我之上的嗜好與煩惱便會冰消瓦解。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-50","chapterId":"cai-gen-tan_ch-5","order":50,"canonicalText":"人情世態，倏忽萬端，不宜認得太真。堯夫雲：「昔日所云我，今朝卻是伊；不知今日我，又屬後來誰？」人常作是觀，便可解卻胸中罥矣。","sentenceIds":["cai-gen-tan_ch-5_p-50_s-1","cai-gen-tan_ch-5_p-50_s-2","cai-gen-tan_ch-5_p-50_s-3","cai-gen-tan_ch-5_p-50_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人世間的情感與局勢，瞬息萬變，不應當看得太過當真。邵康節（堯夫）曾說：「往日所說的那個『我』，如今看來卻像是別人；不知道今天的這個『我』，將來又會屬於哪一個誰呢？」人如果能經常作這樣的觀察與思考，就可以解開胸中一切的名韁利鎖與煩惱束縛了。","analysis":"【主題與背景】本條藉由宋代理學家邵雍（字堯夫）的詩句，探討時空流轉中人性的無常與自我的虛幻。世事如棋，人情冷暖、身份地位皆在「倏忽萬端」地變化，若對眼前的名利得失、恩怨情仇看得太認真，只會徒增痛苦。\\\\n【詞義與名物】邵氏的詩意揭示了自我也是在時間長河中不斷變遷的幻象。\\\\n【思想與篇章】經常作此無常之觀（作是觀），便能放下執念，解開心中被世俗名利所纏繞的絲線（罥，指羅網、纏繞）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-51","chapterId":"cai-gen-tan_ch-5","order":51,"canonicalText":"有一樂境界，就有一不樂的相對待；有一好光景，就有一不好的相乘除。只是尋常家飯、素位風光，才是個安樂窩巢。","sentenceIds":["cai-gen-tan_ch-5_p-51_s-1","cai-gen-tan_ch-5_p-51_s-2","cai-gen-tan_ch-5_p-51_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"只要出現一種快樂的境界，就會有另一種不快樂的境遇與之相對立相伴隨；只要有一段美好的時光，就會有一段不好的際遇與之相抵消。只有那最平常的家常便飯、安守本分的生活景象，才是真正安全快樂的溫馨港灣。","analysis":"【主題與背景】本條蘊含了道家陰陽相生、盛極必衰與中庸平安的思想。世俗的極致快樂（樂境界、好光景）往往伴隨著失落的隱患，因為事物發展到頂點必然走向反面（相對待、相乘除）。\\\\n【詞義與名物】因此，過度追逐感官或功名的狂喜，只會帶來同等程度的痛苦。\\\\n【思想與篇章】唯有甘於「尋常家飯」（平淡生活）與「素位風光」（安守當下本分，語出《中庸》「君子素其位而行，不願乎其外」），不偏不倚，才能獲得持久的安寧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-52","chapterId":"cai-gen-tan_ch-5","order":52,"canonicalText":"知成之必敗，則求成之心不必太堅；知生之必死，則保生之道不必過勞。","sentenceIds":["cai-gen-tan_ch-5_p-52_s-1","cai-gen-tan_ch-5_p-52_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"明白成功之後必然會走向衰敗的道理，那麼追求成功的心思就不必過於執著強求；明白有生就必定有死的自然規律，那麼保養身體生命的方法就不必過於勞神焦慮。","analysis":"【主題與背景】本條融合了老子「物壯則老」與莊子「順應自然」的生死觀。萬事萬物皆在成、住、壞、空的循環中，有「成」必有「敗」，若過於執著於功成名就，一旦失敗便會痛苦不堪，故「求成之心不必太堅」；生命亦是如此，有生必有死，過度喫藥養生、擔憂衰老（過勞於保生），反而違背了生命的自然節奏，損害了當下的心靈安寧。\\\\n【詞義與名物】這是一種順應自然、不強求、不對抗的生活智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-53","chapterId":"cai-gen-tan_ch-5","order":53,"canonicalText":"眼看西晉之荊榛，猶矜白刃；身屬北邙之狐兔，尚惜黃金。語雲：「猛獸易伏，人心難降。溪壑易填，人心難滿」。信哉！","sentenceIds":["cai-gen-tan_ch-5_p-53_s-1","cai-gen-tan_ch-5_p-53_s-2","cai-gen-tan_ch-5_p-53_s-3","cai-gen-tan_ch-5_p-53_s-4","cai-gen-tan_ch-5_p-53_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"眼看著西晉荒廢長滿荊棘的廢墟，人們卻依然在炫耀武力、揮舞兵刃去爭奪；身體明明終將歸於北邙山荒墓、陪伴狐狸與野兔，卻依然在吝惜黃金、貪得無厭。俗話說：「兇猛的野獸容易馴服，浮躁的人心卻難以降伏；深邃的溪流山谷容易填平，貪婪的人心卻永遠無法滿足。」這話真是可信啊！","analysis":"【主題與背景】本條痛斥人類貪欲與權力欲的執迷不悟。「西晉之荊榛」代表歷史的荒涼廢墟，暗示權力鬥爭的虛無；「北邙之狐兔」指洛陽北邙山，是古代著名的墓葬之地，暗示死亡的必然。\\\\n【詞義與名物】世人明知歷史更迭、肉身將死，卻依然在有限的生命裡爭權奪利（矜白刃、惜黃金），展現出人性的貪婪與執著。\\\\n【思想與篇章】引文「猛獸易伏，人心難降。溪壑易填，人心難滿」形象地揭示了降伏自身慾念之難，是佛家修行「降伏其心」的生動寫照。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-54","chapterId":"cai-gen-tan_ch-5","order":54,"canonicalText":"心地上無風濤，隨在皆青山綠樹；性天中有化育，觸處都魚躍鳶飛。","sentenceIds":["cai-gen-tan_ch-5_p-54_s-1","cai-gen-tan_ch-5_p-54_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果心靈深處沒有世俗名利的風浪波濤，那麼所到之處看到的都是青山綠樹般的美好景緻；如果本性之中蘊含著天道滋育萬物的生機，那麼接觸到的每一個地方都呈現出魚躍鳶飛般自由活潑的生命氣象。","analysis":"【主題與背景】本條論述心靈修養對感知世界的影響，融合了儒道兩家的境界。「無風濤」指心境的寧靜，沒有欲望的幹擾，如此一來，即便是身處喧囂，眼中也是一片和諧的「青山綠樹」（境由心生）。\\\\n【詞義與名物】「性天中有化育，觸處都魚躍鳶飛」則化用了《詩經·旱麓》「鳶飛戾天，魚躍於淵」的典故，理學家常以此形容天理流行、萬物各得其所的生機。\\\\n【思想與篇章】若人心中有此生生之機與天理，便能在天地萬物中感受到無窮的生命活力與喜悅。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-55","chapterId":"cai-gen-tan_ch-5","order":55,"canonicalText":"狐眠敗砌，兔走荒臺，盡是當年歌舞之地；露冷黃花，煙迷衰草，悉屬舊時爭戰之場。盛衰何常，強弱安在，念此令人心灰。","sentenceIds":["cai-gen-tan_ch-5_p-55_s-1","cai-gen-tan_ch-5_p-55_s-2","cai-gen-tan_ch-5_p-55_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"狐狸躺在殘破的臺階上睡覺，兔子在荒廢的露臺上奔跑，這些地方全是當年達官顯貴歌舞昇平的娛樂場所；冰冷的露水打濕黃花，濃霧籠罩著枯萎的衰草，這一切全都是過去英雄豪傑廝殺爭奪的戰場。繁榮與衰敗哪有常態，強大與弱小如今又在哪裡？想到這裡，真讓人對世俗的名利爭奪感到心灰意冷。","analysis":"【主題與背景】本條通過歷史遺跡的興衰對比，抒發了深沉的無常之感。「歌舞之地」如今成了「狐眠敗砌，兔走荒臺」，「爭戰之場」變成了「露冷黃花，煙迷衰草」，這種強烈的視覺與歷史對比，深刻揭示了世俗繁華與權力鬥爭的短暫與荒謬。\\\\n【詞義與名物】「盛衰何常，強弱安在」的發問，旨在引導讀者看穿歷史的迷霧，對世俗的功名利祿產生「心灰」（即放下執著），轉而尋求永恆的精神解脫。\\\\n【思想與篇章】這與《三國演義》開篇詞及諸多感懷詩的意境相通。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-56","chapterId":"cai-gen-tan_ch-5","order":56,"canonicalText":"寵辱不驚，閑看庭前花開花落；去留無意，漫隨天外雲卷雲舒。","sentenceIds":["cai-gen-tan_ch-5_p-56_s-1","cai-gen-tan_ch-5_p-56_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對待得寵或受辱都心無波瀾，悠閒地觀看庭院前花朵的開放與凋謝；對於官職的去留都毫不在意，隨意地伴隨著天空中雲彩的聚集與消散。","analysis":"【主題與背景】這是《菜根譚》中最為膾炙人口的名聯，生動地勾勒出超然物外的隱逸境界。「寵辱不驚」指對名利得失泰然處之，不因外界的讚譽或貶低而動搖心志，其心境就如庭前花朵的自然開落，順應天時而無悲無喜；「去留無意」指對官位或居所的去留沒有主觀的執念，其行止就如天邊雲彩的卷舒，隨風飄蕩而無牽無掛。\\\\n【詞義與名物】此聯融合了莊子的逍遙與禪宗的隨緣，是心靈極度自由、與自然和諧相處的最高典範。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-57","chapterId":"cai-gen-tan_ch-5","order":57,"canonicalText":"晴空朗月，何天不可翱翔，而飛蛾獨投夜燭；清泉綠竹，何物不可飲啄，而鴟鴞偏嗜腐鼠。噫！世之不為飛蛾鴟鴞者，幾何人哉！","sentenceIds":["cai-gen-tan_ch-5_p-57_s-1","cai-gen-tan_ch-5_p-57_s-2","cai-gen-tan_ch-5_p-57_s-3","cai-gen-tan_ch-5_p-57_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在晴朗的天空與明亮的月光下，有著多麼廣闊的天空可以自由飛翔，然而飛蛾卻偏偏要投向夜裡的燭火自焚；在清澈的泉水與翠綠的竹林間，有著多麼潔淨的食物可以飲用啄食，然而貓頭鷹（鴟鴞）卻偏偏喜愛喫腐爛的死老鼠。唉！這世上不去做飛蛾與貓頭鷹這樣的人，又能有幾個呢！","analysis":"【主題與背景】本條運用了飛蛾投火與鴟鴞嗜鼠兩個經典比喻，諷刺世人對名利的盲目追逐。「飛蛾投夜燭」比喻世人為追求感官刺激或短暫名利，不惜自取滅亡；「鴟鴞嗜腐鼠」典出《莊子·秋水》，惠子以為莊子要來奪他的相位，莊子便以鴟鴞偏愛腐鼠而害怕鵷鶵（鳳凰）搶食為喻，諷刺惠子將官位當作寶貝。\\\\n【詞義與名物】世人明明可以追求心靈自由（晴空朗月）與高潔的修養（清泉綠竹），卻往往執迷於物慾與權力（燭火、腐鼠），實在是可悲。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-58","chapterId":"cai-gen-tan_ch-5","order":58,"canonicalText":"權貴龍驤，英雄虎戰，以冷眼視之，如蠅聚羶、如蟻兢血；是非蜂起，得失蝟興，以冷情當之，如冶化金，如湯消雪。","sentenceIds":["cai-gen-tan_ch-5_p-58_s-1","cai-gen-tan_ch-5_p-58_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"權貴們像巨龍般高視闊步，英雄們像猛虎般激烈爭鬥，如果用冷靜超脫的眼光來看，這就像蒼蠅聚集在腥羶之物上、螞蟻爭奪著血跡一樣無聊；世間的是非像羣蜂般飛起，得失像刺蝟的毛般紛紛興起，如果用冷靜淡泊的心情來應對，這就像熔爐融化黃金、熱水消融白雪般容易化解。","analysis":"【主題與背景】本條以極具張力的對比，揭示了冷眼觀世與冷情應世的智慧。「龍驤」、「虎戰」看似威風八面，但在超脫者的「冷眼」中，這些對名利的爭奪本質上與「蠅聚羶」、「蟻兢血」一樣庸俗渺小；而面對紛繁複雜的「是非」與「得失」（蜂起、蝟興），若能保持一顆「冷情」（理智、淡泊的心），便能像高溫熔爐化金、開水融雪一般，迅速將矛盾與煩惱消融於無形。\\\\n【詞義與名物】此語體現了莊子式的超然物外與佛教的觀空智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-59","chapterId":"cai-gen-tan_ch-5","order":59,"canonicalText":"真空不空，執相非真，破相亦非真。問世尊如何發付？在世出世，徇欲是苦，絕欲亦是苦，聽吾儕善自修持。","sentenceIds":["cai-gen-tan_ch-5_p-59_s-1","cai-gen-tan_ch-5_p-59_s-2","cai-gen-tan_ch-5_p-59_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載真空不空，執相非真，破相……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】本條深入探討了佛教的大乘中道義理。「真空不空」是佛教核心觀點，指「空」是事物的無自性，而非頑空（什麼都沒有）；「執相」（執著於有）與「破相」（執著於無、空）都是偏見。\\\\n【詞義與名物】作者進而將其應用於處世修行：既不能完全縱欲（徇欲是苦，落於有），也不能極端禁慾以致心灰意冷（絕欲亦是苦，落於無），而應在「在世」與「出世」之間尋找平衡，即中道妙用。\\\\n【思想與篇章】這展現了禪宗圓融世俗與超脫的智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-60","chapterId":"cai-gen-tan_ch-5","order":60,"canonicalText":"烈士讓千乘，貪夫爭一文，人品星淵也，而好名不殊好利；天子營家國，乞人號饔飧，位分霄壤也，而焦思何異焦聲。","sentenceIds":["cai-gen-tan_ch-5_p-60_s-1","cai-gen-tan_ch-5_p-60_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"有正義感的烈士可以放棄千乘大國的王位，而貪婪的小人卻會為了一分錢而爭執不下，他們的人品有如天上的繁星與深淵般天差地別，但烈士愛好名聲的心態與小人貪圖利益的心態其實沒有本質區別；天子操心治理國家，乞丐大聲哀號乞求一頓飯，他們的地位有如雲霄與泥土般天壤之別，但天子的焦慮憂思與乞丐的悲切哀號又有多大差別呢？","analysis":"【主題與背景】本條進行了深刻的哲學還原，揭示了人性本質的相通性。烈士讓國與貪夫爭利，在世俗道德上是「星淵」（天差地別），但在「執著心」上，烈士好名與貪夫好利同樣是為外物所役使（好名不殊好利）；天子與乞丐地位懸殊（霄壤），但從精神狀態來看，天子為家國大政而「焦思」，乞丐為三餐而「焦聲」，其內心的焦慮、痛苦與不得解脫並無二致。\\\\n【詞義與名物】此處體現了莊子《齊物論》的視角，破除世俗的差別相，引導人們放下對名望與地位的執念。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-61","chapterId":"cai-gen-tan_ch-5","order":61,"canonicalText":"性天澄徹，即飢飱渴飲，無非康濟身心；心地沉迷，縱演偈談禪，總是播弄精魄。","sentenceIds":["cai-gen-tan_ch-5_p-61_s-1","cai-gen-tan_ch-5_p-61_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果本性清澈明亮，那麼即使是飢餓時吃飯、口渴時喝水這般尋常生活，無一不是在保養與調適身心；如果內心沉淪迷失，那麼即使是演練佛偈、口談禪理，也只不過是在玩弄心神魂魄、裝模作樣罷了。","analysis":"【主題與背景】本條強調修行的真誠性與內在性，反對流於形式的虛偽。\\\\n【詞義與名物】「性天澄徹」者心無雜念，其日常起居（飢飱渴飲）就是最自然的禪修，能達到身心調和（康濟身心），這契合禪宗「平常心是道」、「砍柴擔水，無非妙道」的思想；相反，若「心地沉迷」（內心執著於名利），即使口頭上大談禪理、寫佛偈，也只是在做表面文章，甚至成為炫耀自我的工具（播弄精魄），對真實的生命毫無益處。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-62","chapterId":"cai-gen-tan_ch-5","order":62,"canonicalText":"人心有真境，非絲非竹而自恬愉，不煙不茗而自清芬。須念凈境空，慮忘形釋，纔得以遊衍其中。","sentenceIds":["cai-gen-tan_ch-5_p-62_s-1","cai-gen-tan_ch-5_p-62_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人的心靈本有一種真實的至美境界，不需要絲竹樂器的伴奏而自然感到恬靜愉快，不需要燃香與品茗而自然散發出清雅的芬芳。這必須要達到雜念消除、心境空明，忘卻憂慮、超脫形骸的狀態，才能在這個境界中悠閒地遨遊流連。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈素位〉第 354 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「人心有真境非絲非竹而自恬愉不煙不茗而自清……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「人」、「心」、「有」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-5_p-62）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-63","chapterId":"cai-gen-tan_ch-5","order":63,"canonicalText":"天地中萬物，人倫中萬情，世界中萬事，以俗眼觀，紛紛各異，以道眼觀，種種是常，何須分別，何須取捨！","sentenceIds":["cai-gen-tan_ch-5_p-63_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對於宇宙天地間的萬事萬物、人倫關係間的各種情感、人類社會中的種種事務，如果用世俗的眼光來看，它們是繁雜紛亂、各不相同的；如果用天道的眼光來看，它們全都是自然規律的常態運行，本來就是一體的，又何必去刻意區分，又何必去盲目取捨呢！","analysis":"【主題與背景】本條是《莊子·齊物論》思想的精妙體現。「俗眼」執著於事物的差別相，因而產生好惡、取捨與紛爭，導致痛苦；「道眼」則能洞察萬物的本質與內在統一性，明白萬事萬物皆是道（天理）的流行與常態（種種是常）。\\\\n【詞義與名物】當人能以「道眼」觀照世界，就能超越對立，消除偏見與執念，達到「不以物喜，不以己悲」的平等心境。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-64","chapterId":"cai-gen-tan_ch-5","order":64,"canonicalText":"纏脫只在自心，心了則屠肆糟糠居然凈土。不然縱一琴一鶴、一花一竹，嗜好雖清，魔障終在。語雲：「能休塵境為真境，未了僧家是俗家。」","sentenceIds":["cai-gen-tan_ch-5_p-64_s-1","cai-gen-tan_ch-5_p-64_s-2","cai-gen-tan_ch-5_p-64_s-3","cai-gen-tan_ch-5_p-64_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載纏脫只在自心，心了則屠肆……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】本條深入剖析了「纏」（束縛）與「脫」（解脫）的本質在於心，而非外在環境。如果內心真正明瞭（心了）、沒有執著，外在環境的惡劣（屠肆、糟糠）便無法動搖其內心的安寧，當下即是「淨土」；反之，若內心執著未除，即便過著高雅的隱士生活（一琴一鶴、一花一竹），這些雅物也會變成另一種「雅障」或「魔障」（即對雅物的貪戀）。\\\\n【詞義與名物】引文「能休塵境為真境，未了僧家是俗家」進一步強調了心性修養的決定性作用。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-65","chapterId":"cai-gen-tan_ch-5","order":65,"canonicalText":"以我轉物者，得固不喜失亦不憂，大地盡屬逍遙；以物役我者，逆固生憎順亦生愛，一毫便生纏縛。","sentenceIds":["cai-gen-tan_ch-5_p-65_s-1","cai-gen-tan_ch-5_p-65_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"能夠用自己的心靈去支配、轉化外物的人，得到了固然不狂喜，失去了也同樣不憂傷，那麼整個天地大地都屬於他逍遙自得的場所；讓外在事物來奴役、支配自己心靈的人，遇到逆境固然產生憎恨，遇到順境也同樣產生貪愛，即使是極微小的一絲牽掛也會產生無盡的束縛。","analysis":"【主題與背景】本條論述了「主動役物」與「被動役於物」的兩種人生境界，源自莊子的「物物而不物於物」與佛教《楞嚴經》「若能轉物，則同如來」。\\\\n【詞義與名物】「以我轉物」是指內心強大、主宰自我，不被外在的得失所左右，因此能隨遇而安，享有真正的自由（逍遙）；「以物役我」則是指內心脆弱，隨外境的順逆而起伏，對順境生貪愛，對逆境生怨恨，哪怕是「一毫」的微小波動，都會成為套在脖子上的枷鎖。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-66","chapterId":"cai-gen-tan_ch-5","order":66,"canonicalText":"試思未生之前有何象貌，又思既死之後有何景色，則萬念灰冷，一性寂然，自可超物處而遊象先。","sentenceIds":["cai-gen-tan_ch-5_p-66_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"試著去想想自己在出生之前有著怎樣的相貌，再去想想自己死亡之後又會是怎樣的景象，那麼世俗的千般雜念就會冷卻熄滅，原本的本性也會回歸寂靜安寧，自然就能夠超脫於物質世界之上，遨遊於宇宙萬物產生之前的無形境界了。","analysis":"【主題與背景】本條引導讀者進行生死本源的冥想。「未生之前」在禪宗中常被稱為「父母未生前本來面目」，「既死之後」則是肉身化為塵土的歸宿。\\\\n【詞義與名物】這兩個維度的思考打破了我們對當下短暫一生的執著。\\\\n【思想與篇章】當意識到生命的前後皆是無形無相的虛空，當下的種種名利爭奪、得失算計（萬念）自然會隨之「灰冷」，而純真的本性（一性）得以顯現。此時，便能「超物處」（超脫物累），「遊象先」（遨遊於有形世界之前的道之境界，語出老子「吾不知誰之子，象帝之先」）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-67","chapterId":"cai-gen-tan_ch-5","order":67,"canonicalText":"優人傅粉調［石朱］，效妍醜於毫端。俄而歌殘場罷，妍醜何存？弈者爭先兢後，較雌雄於著手。俄而局盡子收，雌雄安在？","sentenceIds":["cai-gen-tan_ch-5_p-67_s-1","cai-gen-tan_ch-5_p-67_s-2","cai-gen-tan_ch-5_p-67_s-3","cai-gen-tan_ch-5_p-67_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"戲曲演員在臉上塗抹脂粉、調和硃砂，用畫筆將美麗與醜陋的妝容展現在細微的筆端。然而不久之後，戲曲唱完、曲終人散，那些所謂的美麗與醜陋又在哪裡呢？下棋的人為了爭奪先手而戰戰兢兢、互不相讓，在每一次落子時都要與對手較量出高低勝負。然而不久之後，棋局結束、棋子收起，那些所謂的勝負高下又在哪裡呢？","analysis":"【訓詁與名物】「優人」指古代的戲曲演員或優伶。「傅粉調［石朱］」指演員化妝，傅粉即塗白粉，［石朱］（硃）指紅色顏料。「效妍醜於毫端」指用畫筆（毫端）描繪出美（妍）與醜的各種角色容貌。「俄而」意為不久、片刻之後。「歌殘場罷」指演出結束。「弈者」即下棋的人。「爭先兢後」形容下棋時害怕落後、拼命爭取主動權的緊張狀態。「較雌雄於著手」指在下棋的過程中較量勝負。「局盡子收」指下完棋，將棋子收回棋盒中。\\\\n【章法與結構】本段採用了極為工整的駢文結構，前半段以「優人演戲」為喻，後半段以「弈者下棋」為喻。兩者皆遵循「過程中的執著與計較（效妍醜、較雌雄）」轉至「結束後的虛無與空幻（妍醜何存、雌雄安在）」的敘事邏輯，並以兩次反問作結，首尾呼應，語意深長。\\\\n【思想與義理】此段文字洋溢著濃厚的人生如戲、世事如棋的禪道哲思。作者藉由演戲時的美醜之分與下棋時的勝負之爭，隱喻世俗中人們對於名利、地位、美醜、勝負的汲汲營營。然而，就如同戲終落幕、棋局結束一般，生命的終點到來時，一切外在的計較與爭奪終將歸於虛無。這啟發我們要以超然的態度看待人生的得失，不執著於一時的勝敗美醜，從中獲得心靈的解脫與自在。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-68","chapterId":"cai-gen-tan_ch-5","order":68,"canonicalText":"把握未定，宜絕跡塵囂，使此心不見可欲而不亂，以澄吾靜體；操持既堅，又當混跡風塵，使此心見可欲而亦不亂，以養吾圓機。","sentenceIds":["cai-gen-tan_ch-5_p-68_s-1","cai-gen-tan_ch-5_p-68_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當自己的意志與定力還不夠堅定、無法自我掌控時，應當遠離喧囂的塵俗，使這顆心接觸不到引起慾望的事物而不致混亂，以此來澄清我們寧靜的本體；當心志的操守已經堅固成熟時，又應當深入到滾滾紅塵之中，使這顆心即使看到了誘發慾望的事物也同樣不為所動，以此來培養我們圓融應變的智慧。","analysis":"【主題與背景】本條提出了修身養性的兩個階段與方法，極具實踐指導意義。第一階段是「把握未定」時，應採取避世的消極防禦，避免誘惑（不見可欲，語出《老子》「不見可欲，使民心不亂」），以培育內心的寧靜根基（澄吾靜體）；第二階段是「操持既堅」後，應主動入世磨練（混跡風塵），在誘惑中考驗定力（見可欲而亦不亂），從而達到隨機應變、圓通無礙的境界（養吾圓機）。\\\\n【詞義與名物】這體現了由小乘的避世修行走向大乘的入世度人的辯證過程。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-69","chapterId":"cai-gen-tan_ch-5","order":69,"canonicalText":"喜寂厭喧者，往往避人以求靜。不知意在無人，便成我相，心著於靜，便是動根。如何到得人我一空、動靜兩忘的境界！","sentenceIds":["cai-gen-tan_ch-5_p-69_s-1","cai-gen-tan_ch-5_p-69_s-2","cai-gen-tan_ch-5_p-69_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載喜寂厭喧者，往往避人以求……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】本條直指禪修與修心過程中容易陷入的偏見——「執靜為靜」。真正的靜不是物理環境的無聲，而是內心的無罣礙。\\\\n【詞義與名物】如果為了求靜而故意避開人羣（避人），心中就已經對「人」與「我」產生了分別（成我相）；如果一味追求「靜」，討厭「動」，這種對靜的強烈執著本身就是一種妄動（動根）。\\\\n【思想與篇章】唯有達到「人我一空、動靜兩忘」的境地，才能實現真正的、超越動靜對立的真靜。這體現了禪宗不二法門與六祖「惠能無伎倆，不斷百思想」的境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-70","chapterId":"cai-gen-tan_ch-5","order":70,"canonicalText":"人生禍區福境，皆念想造成。故釋氏雲：刊欲熾然，即是火坑。貪愛沉溺，便為苦海。一念清凈，烈焰成池。一念驚覺，航登彼岸。念頭稍異，境界頓殊。可不慎哉！繩鋸材斷，水滴石穿，學道者須要努索；水到渠成，瓜熟蒂落，得道者一任天機。","sentenceIds":["cai-gen-tan_ch-5_p-70_s-1","cai-gen-tan_ch-5_p-70_s-2","cai-gen-tan_ch-5_p-70_s-3","cai-gen-tan_ch-5_p-70_s-4","cai-gen-tan_ch-5_p-70_s-5","cai-gen-tan_ch-5_p-70_s-6","cai-gen-tan_ch-5_p-70_s-7","cai-gen-tan_ch-5_p-70_s-8","cai-gen-tan_ch-5_p-70_s-9"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人生的災禍境地與福德境界，全都是由人自己的心念所造成的。所以佛家說：情慾燃燒得像烈火一樣熾熱，當下就是火坑；貪圖享樂、沉溺不拔，立刻就成了苦海。如果能保持一念的清淨，熾熱的烈火也能化作清涼的蓮池；如果能有一念的警醒覺悟，迷茫的靈魂當下就能登上解脫的彼岸。心念稍微有所不同，所處的境界就會頓時產生天壤之別，這能不謹慎嗎！用繩子鋸木頭木頭會斷，水滴滴在石頭上石頭會穿，求學修道的人必須要努力探索、堅持不懈；水流到的地方渠溝自然形成，瓜果成熟了果蒂自然脫落，悟道成功的人則一切聽憑自然規律的運行。","analysis":"【主題與背景】本條包含兩段重要的修養道理：前半段論述「境由心造」的佛理，強調念頭（念想）對人生境遇的決定性作用，貪欲與清淨、火坑與蓮池（烈焰成池，指阿鼻地獄的烈火化作八功德水）、苦海與彼岸，皆在起心動唸的一瞬間；後半段論述修道與得道的辯證關係，修道階段需要像「繩鋸木斷、水滴石穿」那樣付出持久的「努索」（努力探索、奮鬥），而一旦「得道」，則應如同「水到渠成、瓜熟蒂落」般順應自然，不加人工雕琢（一任天機）。\\\\n【詞義與名物】段落涵括關鍵處世概念與典故範疇，展現明代格言對心靈調適與涵養的重視。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-71","chapterId":"cai-gen-tan_ch-5","order":71,"canonicalText":"就一身了一身者，方能以萬物付萬物；還天下於天下者，方能出世間於世間。","sentenceIds":["cai-gen-tan_ch-5_p-71_s-1","cai-gen-tan_ch-5_p-71_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"能夠在自我立身處世上徹底了悟、解脫自身的人，才能夠順應自然，把萬物的運行交付給萬物自身；能夠把天下的權力與名利歸還給天下所有人的人，才能夠在世俗的涉世之中展現出超然出世的胸襟。","analysis":"【主題與背景】本條探討修身、治國與出世的最高境界。\\\\n【詞義與名物】「就一身了一身」是指徹底解決了自我的生死與執著問題，達到了「無我」的境界，如此才能不以主觀偏見幹預世界，實現「以萬物付萬物」（順應萬物之自然運行）；「還天下於天下」則化用了《莊子》與《呂氏春秋·貴公》「天下非一人之天下，天下之天下也」的思想，將名利與權力徹底放下，不據為己有，唯有具備這種大公無私的胸懷，才能在繁忙的世俗事務中（在世間）保持出世的超然與從容。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-72","chapterId":"cai-gen-tan_ch-5","order":72,"canonicalText":"人生原是傀儡，只要把柄在手，一線不亂，卷舒自由，行止在我，一毫不受他人捉掇，便超此場中矣。","sentenceIds":["cai-gen-tan_ch-5_p-72_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人生本來就像是一場木偶戲，只要將控制木偶的把柄牢牢掌握在自己手中，控制提線不亂，能夠自由收放，行動與停止都由自己作主，一分一毫也不受旁人的擺佈與操縱，就可以超越這場人生戲局了。","analysis":"【主題與背景】本條以木偶戲（傀儡）為喻，探討主宰命運、獲得精神獨立的智慧。世俗之人往往被名利、輿論與社會成見的提線所牽引，成為隨人擺佈的傀儡而不自知。\\\\n【詞義與名物】作者指出，要超越這場荒謬的「人生戲局」（此場中），關鍵在於將命運的「把柄」收回到自己手中，做到「行止在我」（自我做主，不受外界幹擾），保持內心的主體性與定力。\\\\n【思想與篇章】這融合了道家追求個體自由與儒家獨立不遷的人格尊嚴。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-73","chapterId":"cai-gen-tan_ch-5","order":73,"canonicalText":"「為鼠常留飯，憐蛾不點燈」，古人此點念頭，是吾一點生生之機，列此即所謂土木形骸而已。","sentenceIds":["cai-gen-tan_ch-5_p-73_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在慾念極其濃厚熾熱之際，若能保持一份冷靜客觀的頭腦，往往能獲得頓悟超脫的契機；在心境歸於冷靜沉寂之後，若能煥發出一份熱忱為善的心志，往往能體悟到天地造化宇宙萬物的無窮妙用。","analysis":"【主題與背景】本條歌頌了儒家與佛教慈悲仁愛思想的結合。「為鼠常留飯，憐蛾不點燈」語出唐代蘇軾《次韻僧潛見贈》詩中的「愛鼠常留飯，憐蛾不點燈」，展現了對微小生命無私的關懷與悲憫。\\\\n【詞義與名物】作者指出，這種悲憫之念（生生之機）是人之所以為人、心靈具有靈性與善意的核心；若無此仁愛之心，人即便活著，也只不過是空有肉體軀殼的「土木形骸」（泥塑木雕）。\\\\n【思想與篇章】此語強調了善念與同理心對於涵養人性與心靈的重要價值。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-5_p-74","chapterId":"cai-gen-tan_ch-5","order":74,"canonicalText":"世態有炎涼，而我無嗔喜；世味有濃淡，而我無欣厭。一毫不落世情窠臼，便是一在世出世法也。","sentenceIds":["cai-gen-tan_ch-5_p-74_s-1","cai-gen-tan_ch-5_p-74_s-2","cai-gen-tan_ch-5_p-74_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世間的人情態勢固然有熱情與冷酷的變化，但我的內心卻不會因此而生出怨恨或狂喜；世俗的生活滋味固然有繁華與清苦的分別，但我的內心卻不會因此而產生嚮往或厭惡。只要一絲一毫都不落入世俗人情所設定的刻板框架中，這便是一種身處塵世之中卻能超越塵俗之外的修行法則。","analysis":"【訓詁與名物】「世態」指社會上的人情世故與世俗的態度。「炎涼」比喻人情的冷暖厚薄，炎即熱情趨附，涼即冷漠疏遠。「嗔喜」即怨恨（嗔）與歡喜。「世味」指世俗生活的各種滋味與境遇。「濃淡」比喻生活的富貴繁華（濃）與貧窮清苦（淡）。「欣厭」即欣慕與厭惡。「窠臼」原指鳥獸的巢穴或舂米的石臼，比喻現成的格式、老套或俗套。「在世出世法」借用佛教術語，指既生活在世俗之中（入世），在精神上又能超越世俗牽絆（出世）的境界與方法。\\\\n【章法與結構】前兩句對仗工整，「世態有炎涼」對應「世味有濃淡」，「我無嗔喜」對應「我無欣厭」，明確表達了客觀環境的變幻無常與主觀心境的如如不動之間的對比。最後一句則進行總結與昇華，點出「不落窠臼」的具體作法與「在世出世」的最高境界，邏輯清晰，擲地有聲。\\\\n【思想與義理】這段話是儒釋道三家思想融合的典型體現，探討了「入世」與「出世」的圓融境界。一般人容易隨外境流轉，因人情冷暖而悲喜，因生活貧富而貪嗔；但有修養的君子深知世事無常，因此能夠修煉出一顆不為外物所動的平平靜靜之心。作者指出，真正的出世並非要逃離社會、隱居山林，而是在日常生活中保持心靈的獨立與超越，不被世俗的價值觀所綁架。這種「心淨則國土淨」的境界，正是修行者在塵世中獲得大自在的最高智慧。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"cai-gen-tan_ch-5_p-1_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-1","order":1,"canonicalText":"道是一件公眾的物事，當隨人而接引；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-1_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-1","order":2,"canonicalText":"學是一個尋常的家飯，當隨事而警惕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-2_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-2","order":1,"canonicalText":"念頭寬厚的，如春風煦育，萬物遭之而生；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-2_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-2","order":2,"canonicalText":"念頭忌尅的，如朔雪陰凝，萬物遭之而死。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-3_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-3","order":1,"canonicalText":"勤者敏於德義，而世人借勤以濟其貪；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-3_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-3","order":2,"canonicalText":"儉者淡於貨利，而世人假儉以飾其吝。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-3_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-3","order":3,"canonicalText":"君子持身之符，反為小人營私之具矣，惜哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-4_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-4","order":1,"canonicalText":"人之過誤宜恕，而在己則不可恕；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-4_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-4","order":2,"canonicalText":"己之困辱宜忍，而在人則不可忍。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-5_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-5","order":1,"canonicalText":"恩宜自淡而濃，先濃後淡者人忘其惠；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-5_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-5","order":2,"canonicalText":"威宜自嚴而寬，先寬後嚴者人怨其酷。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-6_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-6","order":1,"canonicalText":"士君子處權門要路，操履要嚴明，心氣要和易。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-6_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-6","order":2,"canonicalText":"毋少隨而近腥羶之黨，亦毋過激而犯蜂蠆之毒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-7_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-7","order":1,"canonicalText":"遇欺詐的人，以誠心感動之；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-7_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-7","order":2,"canonicalText":"遇暴戾的人，以和氣燻蒸之；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-7_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-7","order":3,"canonicalText":"遇傾邪私曲的人，以名義氣節激勵之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-7_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-7","order":4,"canonicalText":"天下無不入我陶鎔中矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-8_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-8","order":1,"canonicalText":"一念慈祥，可以醞釀兩間和氣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-8_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-8","order":2,"canonicalText":"寸心潔白，可以昭垂百代清芬。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-9_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-9","order":1,"canonicalText":"陰謀怪習、異行奇能，俱是涉世的禍胎。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-9_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-9","order":2,"canonicalText":"只一個庸德庸行，便可以完混沌而招和平。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-10_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-10","order":1,"canonicalText":"語雲：「登山耐險路，踏雪耐危橋」。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-10_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-10","order":2,"canonicalText":"一耐字極有意味。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-10_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-10","order":3,"canonicalText":"如傾險之人情、坎坷之世道，若不得一耐字撐持過去，幾何不墜入榛莽坑塹哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-11_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-11","order":1,"canonicalText":"誇逞功業炫耀文章，皆是靠外物做人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-11_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-11","order":2,"canonicalText":"不知心體瑩然，本來不失，即無寸功隻字，亦自有堂堂正正做人處。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-12_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-12","order":1,"canonicalText":"不昧己心，不拂人情，不竭物力，三者可以為天地立心，為生民立命，為子孫造福。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-13_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-13","order":1,"canonicalText":"居官有二語曰：「惟公則生明，惟廉則生威」。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-13_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-13","order":2,"canonicalText":"居家有二語曰：「惟恕則平情，惟儉則足用」。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-14_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-14","order":1,"canonicalText":"處富貴之地，要知貧賤的痛癢；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-14_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-14","order":2,"canonicalText":"當少壯之時，須念衰老的辛酸。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-15_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-15","order":1,"canonicalText":"持身不可太皎潔，一切污辱垢穢要茹納的；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-15_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-15","order":2,"canonicalText":"與人不可太分明，一切善惡賢愚要包容的。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-16_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-16","order":1,"canonicalText":"休與小人仇讎，小人自有對頭；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-16_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-16","order":2,"canonicalText":"休向君子諂媚，君子原無私惠。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-17_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-17","order":1,"canonicalText":"磨［石厲］當如百煉之金，急就者非邃養施為宜。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-17_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-17","order":2,"canonicalText":"似千鈞之弩，輕發者無宏功。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-18_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-18","order":1,"canonicalText":"建功立業者，多虛圓之士；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-18_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-18","order":2,"canonicalText":"僨事失機者，必執拗之人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-19_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-19","order":1,"canonicalText":"儉，美德也，過則為慳吝、為鄙嗇，反傷雅道；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-19_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-19","order":2,"canonicalText":"讓，懿行也，過則為足恭、為曲禮，多出機心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-20_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-20","order":1,"canonicalText":"毋憂拂意，毋喜快心，毋恃久安，毋憚初難。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-21_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-21","order":1,"canonicalText":"飲宴之樂多，不是個好人家。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-21_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-21","order":2,"canonicalText":"聲華之習勝，不是個好士子。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-21_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-21","order":3,"canonicalText":"名位之念重，不是個好臣工。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-22_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-22","order":1,"canonicalText":"仁人心地寬舒，便福厚而慶長，事事成個寬舒氣象；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-22_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-22","order":2,"canonicalText":"鄙夫念頭迫促，便祿薄而澤短，事事成個迫促規模。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-23_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-23","order":1,"canonicalText":"用人不宜刻，刻則思效者去；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-23_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-23","order":2,"canonicalText":"交友不宜濫，濫則貢諛者來。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-24_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-24","order":1,"canonicalText":"大人不可不畏，畏大人則無放逸之心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-24_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-24","order":2,"canonicalText":"小民亦不可不畏，畏小民則無豪橫之名。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-25_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-25","order":1,"canonicalText":"事稍拂逆，便思不如我的人，則怨尤自消；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-25_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-25","order":2,"canonicalText":"心稍怠荒，便思勝似我的人，則精神自奮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-26_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-26","order":1,"canonicalText":"不可乘喜而輕諾，不可因醉而生［目真］，不可乘快而多事，不可因倦而鮮終。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-27_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-27","order":1,"canonicalText":"釣水，逸事也，尚持生殺之柄；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-27_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-27","order":2,"canonicalText":"弈棋，清戲也，且動戰爭之心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-27_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-27","order":3,"canonicalText":"可見喜事不如省事之為適，多能不如無能之全真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-28_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-28","order":1,"canonicalText":"聽靜夜之鐘聲，喚醒夢中之夢；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-28_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-28","order":2,"canonicalText":"觀澄潭之月影，窺見身外之身。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-29_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-29","order":1,"canonicalText":"鳥語蟲聲，總是傳心之訣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-29_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-29","order":2,"canonicalText":"花英草色，無非見道之文。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-29_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-29","order":3,"canonicalText":"學者要天機清徹，胸次玲瓏，觸物皆有會心處。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-30_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-30","order":1,"canonicalText":"人解讀有字書，不解讀無字書；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-30_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-30","order":2,"canonicalText":"知彈有絃琴，不知彈無絃琴。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-30_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-30","order":3,"canonicalText":"以跡用不以神用，何以得琴書佳趣？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-31_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-31","order":1,"canonicalText":"山河大地已屬微塵，而況塵中之塵！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-31_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-31","order":2,"canonicalText":"血肉身驅且歸泡影，而況影外之影！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-31_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-31","order":3,"canonicalText":"非上上智，無了了心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-32_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-32","order":1,"canonicalText":"石火光中，爭長兢短，幾何光陰？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-32_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-32","order":2,"canonicalText":"蝸牛角上，較雌論雄，許大世界？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-33_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-33","order":1,"canonicalText":"有浮雲富貴之風，而不必巖棲穴處；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-33_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-33","order":2,"canonicalText":"無膏盲泉石之癖，而常自醉酒耽詩。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-33_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-33","order":3,"canonicalText":"兢逐聽人而不嫌盡醉，恬［心詹］適己而不誇獨醒，此釋氏所謂不為法纏、不為空纏，身心兩自在者。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-34_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-34","order":1,"canonicalText":"延促由於一念，寬窄係之寸心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-34_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-34","order":2,"canonicalText":"故機閑者一日遙於千古，意寬者斗室廣於兩間。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-35_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-35","order":1,"canonicalText":"都來眼前事，知足者仙境，不知足者凡境；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-35_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-35","order":2,"canonicalText":"總出世上因，善用者生機，不善用者殺機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-36_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-36","order":1,"canonicalText":"趨炎附勢之禍，甚慘亦甚速；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-36_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-36","order":2,"canonicalText":"棲恬守逸之味，最淡亦最長。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-37_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-37","order":1,"canonicalText":"色慾火熾，而一念及病時，便興似寒灰；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-37_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-37","order":2,"canonicalText":"名利飴甘，而一想到死地，便味如咀蠟。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-37_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-37","order":3,"canonicalText":"故人常憂死慮病，亦可消幻業而長道心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-38_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-38","order":1,"canonicalText":"爭先的徑路窄，退後一步自寬平一步；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-38_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-38","order":2,"canonicalText":"濃艷的滋味短，清淡一分自悠長一分。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-39_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-39","order":1,"canonicalText":"隱逸林中無榮辱，道義路上泯炎涼。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-39_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-39","order":2,"canonicalText":"進步處便思退步，庶免觸藩之禍。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-39_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-39","order":3,"canonicalText":"著手時光圖放手，纔脫騎虎之危。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-40_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-40","order":1,"canonicalText":"貪得者分金恨不得玉，封公怨不授侯，權豪自甘乞丐；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-40_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-40","order":2,"canonicalText":"知足者藜羹旨於膏梁，布袍暖於狐貉，編民不讓王公。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-41_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-41","order":1,"canonicalText":"矜名不如逃名趣，練事何如省事閒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-41_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-41","order":2,"canonicalText":"孤雲出岫，去留一無所係；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-41_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-41","order":3,"canonicalText":"朗鏡懸空，靜躁兩不相干。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-42_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-42","order":1,"canonicalText":"山林是勝地，一營戀便成市朝；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-42_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-42","order":2,"canonicalText":"書畫是雅事，一貪癡便成商賈。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-42_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-42","order":3,"canonicalText":"蓋心無染著，俗境是仙都；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-42_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-42","order":4,"canonicalText":"心有絲牽，樂境成悲地。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-43_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-43","order":1,"canonicalText":"時當喧雜，則平日所記憶者皆漫然忘去；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-43_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-43","order":2,"canonicalText":"境在清寧，則夙昔所遺忘者又恍爾現前。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-43_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-43","order":3,"canonicalText":"可見靜躁稍分，昏明頓異也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-44_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-44","order":1,"canonicalText":"蘆花被下臥雪眠雲，保全得一窩夜氣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-44_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-44","order":2,"canonicalText":"竹葉杯中吟風弄月，躲離了萬丈紅塵。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-45_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-45","order":1,"canonicalText":"出世之道，即在涉世中，不必絕人以逃世；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-45_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-45","order":2,"canonicalText":"了心之功即在盡心內，不必絕欲以灰心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-46_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-46","order":1,"canonicalText":"此身常放在閒處，榮辱得失，誰能差遣我？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-46_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-46","order":2,"canonicalText":"此心常安在靜中，是非利害，誰能瞞昧我？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-47_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-47","order":1,"canonicalText":"我不希榮，何憂乎利祿之香餌；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-47_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-47","order":2,"canonicalText":"我不兢進，何畏乎仕宦之危機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-48_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-48","order":1,"canonicalText":"多藏厚亡，故知富不如貧之無慮；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-48_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-48","order":2,"canonicalText":"高步疾顛，故知貴不如賤之常安。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-49_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-49","order":1,"canonicalText":"世上只緣認得「我」字太真，故多種種嗜好、種種煩惱。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-49_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-49","order":2,"canonicalText":"前人云：「不復知有我，安知物為貴。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-49_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-49","order":3,"canonicalText":"」又云：「知身不是我，煩惱更何侵。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-49_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-49","order":4,"canonicalText":"」真破的之言也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-50_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-50","order":1,"canonicalText":"人情世態，倏忽萬端，不宜認得太真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-50_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-50","order":2,"canonicalText":"堯夫雲：「昔日所云我，今朝卻是伊；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-50_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-50","order":3,"canonicalText":"不知今日我，又屬後來誰？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-50_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-50","order":4,"canonicalText":"」人常作是觀，便可解卻胸中罥矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-51_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-51","order":1,"canonicalText":"有一樂境界，就有一不樂的相對待；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-51_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-51","order":2,"canonicalText":"有一好光景，就有一不好的相乘除。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-51_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-51","order":3,"canonicalText":"只是尋常家飯、素位風光，才是個安樂窩巢。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-52_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-52","order":1,"canonicalText":"知成之必敗，則求成之心不必太堅；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-52_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-52","order":2,"canonicalText":"知生之必死，則保生之道不必過勞。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-53_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-53","order":1,"canonicalText":"眼看西晉之荊榛，猶矜白刃；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-53_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-53","order":2,"canonicalText":"身屬北邙之狐兔，尚惜黃金。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-53_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-53","order":3,"canonicalText":"語雲：「猛獸易伏，人心難降。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-53_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-53","order":4,"canonicalText":"溪壑易填，人心難滿」。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-53_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-53","order":5,"canonicalText":"信哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-54_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-54","order":1,"canonicalText":"心地上無風濤，隨在皆青山綠樹；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-54_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-54","order":2,"canonicalText":"性天中有化育，觸處都魚躍鳶飛。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-55_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-55","order":1,"canonicalText":"狐眠敗砌，兔走荒臺，盡是當年歌舞之地；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-55_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-55","order":2,"canonicalText":"露冷黃花，煙迷衰草，悉屬舊時爭戰之場。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-55_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-55","order":3,"canonicalText":"盛衰何常，強弱安在，念此令人心灰。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-56_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-56","order":1,"canonicalText":"寵辱不驚，閑看庭前花開花落；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-56_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-56","order":2,"canonicalText":"去留無意，漫隨天外雲卷雲舒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-57_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-57","order":1,"canonicalText":"晴空朗月，何天不可翱翔，而飛蛾獨投夜燭；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-57_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-57","order":2,"canonicalText":"清泉綠竹，何物不可飲啄，而鴟鴞偏嗜腐鼠。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-57_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-57","order":3,"canonicalText":"噫！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-57_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-57","order":4,"canonicalText":"世之不為飛蛾鴟鴞者，幾何人哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-58_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-58","order":1,"canonicalText":"權貴龍驤，英雄虎戰，以冷眼視之，如蠅聚羶、如蟻兢血；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-58_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-58","order":2,"canonicalText":"是非蜂起，得失蝟興，以冷情當之，如冶化金，如湯消雪。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-59_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-59","order":1,"canonicalText":"真空不空，執相非真，破相亦非真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-59_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-59","order":2,"canonicalText":"問世尊如何發付？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-59_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-59","order":3,"canonicalText":"在世出世，徇欲是苦，絕欲亦是苦，聽吾儕善自修持。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-60_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-60","order":1,"canonicalText":"烈士讓千乘，貪夫爭一文，人品星淵也，而好名不殊好利；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-60_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-60","order":2,"canonicalText":"天子營家國，乞人號饔飧，位分霄壤也，而焦思何異焦聲。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-61_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-61","order":1,"canonicalText":"性天澄徹，即飢飱渴飲，無非康濟身心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-61_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-61","order":2,"canonicalText":"心地沉迷，縱演偈談禪，總是播弄精魄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-62_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-62","order":1,"canonicalText":"人心有真境，非絲非竹而自恬愉，不煙不茗而自清芬。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-62_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-62","order":2,"canonicalText":"須念凈境空，慮忘形釋，纔得以遊衍其中。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-63_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-63","order":1,"canonicalText":"天地中萬物，人倫中萬情，世界中萬事，以俗眼觀，紛紛各異，以道眼觀，種種是常，何須分別，何須取捨！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-64_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-64","order":1,"canonicalText":"纏脫只在自心，心了則屠肆糟糠居然凈土。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-64_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-64","order":2,"canonicalText":"不然縱一琴一鶴、一花一竹，嗜好雖清，魔障終在。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-64_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-64","order":3,"canonicalText":"語雲：「能休塵境為真境，未了僧家是俗家。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-64_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-64","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-65_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-65","order":1,"canonicalText":"以我轉物者，得固不喜失亦不憂，大地盡屬逍遙；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-65_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-65","order":2,"canonicalText":"以物役我者，逆固生憎順亦生愛，一毫便生纏縛。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-66_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-66","order":1,"canonicalText":"試思未生之前有何象貌，又思既死之後有何景色，則萬念灰冷，一性寂然，自可超物處而遊象先。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-67_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-67","order":1,"canonicalText":"優人傅粉調［石朱］，效妍醜於毫端。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-67_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-67","order":2,"canonicalText":"俄而歌殘場罷，妍醜何存？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-67_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-67","order":3,"canonicalText":"弈者爭先兢後，較雌雄於著手。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-67_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-67","order":4,"canonicalText":"俄而局盡子收，雌雄安在？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-68_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-68","order":1,"canonicalText":"把握未定，宜絕跡塵囂，使此心不見可欲而不亂，以澄吾靜體；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-68_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-68","order":2,"canonicalText":"操持既堅，又當混跡風塵，使此心見可欲而亦不亂，以養吾圓機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-69_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-69","order":1,"canonicalText":"喜寂厭喧者，往往避人以求靜。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-69_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-69","order":2,"canonicalText":"不知意在無人，便成我相，心著於靜，便是動根。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-69_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-69","order":3,"canonicalText":"如何到得人我一空、動靜兩忘的境界！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":1,"canonicalText":"人生禍區福境，皆念想造成。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":2,"canonicalText":"故釋氏雲：刊欲熾然，即是火坑。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":3,"canonicalText":"貪愛沉溺，便為苦海。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":4,"canonicalText":"一念清凈，烈焰成池。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":5,"canonicalText":"一念驚覺，航登彼岸。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-6","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":6,"canonicalText":"念頭稍異，境界頓殊。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-7","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":7,"canonicalText":"可不慎哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-8","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":8,"canonicalText":"繩鋸材斷，水滴石穿，學道者須要努索；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-70_s-9","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-70","order":9,"canonicalText":"水到渠成，瓜熟蒂落，得道者一任天機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-71_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-71","order":1,"canonicalText":"就一身了一身者，方能以萬物付萬物；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-71_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-71","order":2,"canonicalText":"還天下於天下者，方能出世間於世間。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-72_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-72","order":1,"canonicalText":"人生原是傀儡，只要把柄在手，一線不亂，卷舒自由，行止在我，一毫不受他人捉掇，便超此場中矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-73_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-73","order":1,"canonicalText":"「為鼠常留飯，憐蛾不點燈」，古人此點念頭，是吾一點生生之機，列此即所謂土木形骸而已。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-74_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-74","order":1,"canonicalText":"世態有炎涼，而我無嗔喜；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-74_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-74","order":2,"canonicalText":"世味有濃淡，而我無欣厭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-5_p-74_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-5","passageId":"cai-gen-tan_ch-5_p-74","order":3,"canonicalText":"一毫不落世情窠臼，便是一在世出世法也。","chunks":[],"tags":[]}]}');export{a as default};
